/**
 * 位置编辑弹窗 — 修改名称、地址、备注
 */

'use client';

import { Popup, Form, Input, TextArea, Button, Toast, NavBar } from 'antd-mobile';
import { useState, useEffect } from 'react';

import type { Location } from '../types';

/**
 * 位置编辑弹窗，支持修改名称、地址和备注
 *
 * 表单值在 visible 变为 true 时从 location prop 同步初始化。
 * 保存通过父组件传入的 onSave 回调完成，不直接操作数据源。
 */
export function LocationEditPopup({
  location,
  visible,
  onClose,
  onSave,
}: {
  location: Location | null;
  visible: boolean;
  onClose: () => void;
  onSave: (id: string, data: Partial<Location>) => Promise<Location>;
}) {
  const [name, setName] = useState('');
  const [address, setAddress] = useState('');
  const [comments, setComments] = useState('');
  const [saving, setSaving] = useState(false);

  useEffect(() => {
    if (visible && location) {
      setName(location.name);
      setAddress(location.address);
      setComments(location.comments);
    }
  }, [visible, location]);

  /**
   * 提交编辑表单 —— 调用父组件 onSave 执行 Server Action 持久化，
   * 成功后关闭弹窗，失败时打 ERROR 日志并 Toast 提示。
   */
  async function handleSave() {
    if (!location) return;
    setSaving(true);
    try {
      await onSave(location.id, { name, address, comments });
      Toast.show({ icon: 'success', content: '保存成功' });
      onClose();
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : '保存失败';
      console.error('[Travel] 编辑位置失败:', err, { locationId: location.id });
      if (err instanceof Error && err.stack) console.error(err.stack);
      Toast.show({ icon: 'fail', content: message });
    } finally {
      setSaving(false);
    }
  }

  return (
    <Popup
      visible={visible}
      onMaskClick={onClose}
      onClose={onClose}
      position="bottom"
      bodyStyle={{
        borderTopLeftRadius: 16,
        borderTopRightRadius: 16,
        minHeight: '50vh',
        maxHeight: '75vh',
        overflow: 'auto',
      }}
    >
      <NavBar
        onBack={onClose}
        right={
          <Button color="primary" size="small" loading={saving} onClick={handleSave}>
            保存
          </Button>
        }
      >
        编辑位置
      </NavBar>
      <Form layout="vertical" style={{ padding: '0 16px' }}>
        <Form.Item label="名称">
          <Input value={name} onChange={setName} placeholder="位置名称" />
        </Form.Item>
        <Form.Item label="地址">
          <Input value={address} onChange={setAddress} placeholder="地址" />
        </Form.Item>
        <Form.Item label="备注">
          <TextArea
            value={comments}
            onChange={setComments}
            placeholder="备注"
            rows={3}
          />
        </Form.Item>
      </Form>
    </Popup>
  );
}

/**
 * 位置列表项 — 支持左滑操作（切换状态/删除），有精彩瞬间时状态锁定
 */

'use client';

import { Dialog, List, SwipeAction, Toast } from 'antd-mobile';

import { CoverImage } from './cover-image';
import { StatusTag } from './status-tag';

import type { Location } from '../types';

function getErrorMessage(err: unknown, fallback: string): string {
  if (err instanceof Error) return err.message || fallback;
  return fallback;
}

/**
 * 位置列表行组件
 *
 * 基于 antd-mobile SwipeAction 实现左滑操作 ——
 * 切换状态（已有精彩瞬间时隐藏）和删除（需二次确认）。
 * 点击行触发 onClick 回调。
 */
export function LocationListItem({
  location,
  hasMoments,
  onClick,
  onToggle,
  onDelete,
}: {
  location: Location;
  hasMoments: boolean;
  onClick: (location: Location) => void;
  onToggle: (location: Location) => Promise<void>;
  onDelete: (location: Location) => Promise<void>;
}) {
  const iconUrl = `/travel/api/download?type=icon&id=${location.id}`;

  /**
   * 左滑切换位置状态 —— 调用父组件 onToggle 执行 Server Action，
   * 失败时打 ERROR 日志并 Toast 提示。
   */
  async function handleToggle() {
    try {
      await onToggle(location);
    } catch (err: unknown) {
      console.error('[Travel] 切换位置状态失败:', err, { locationId: location.id });
      if (err instanceof Error && err.stack) console.error(err.stack);
      Toast.show({ icon: 'fail', content: getErrorMessage(err, '操作失败') });
    }
  }

  /**
   * 左滑删除位置 —— 二次确认后调用父组件 onDelete 执行 Server Action，
   * 失败时打 ERROR 日志并 Toast 提示。
   */
  function handleDelete() {
    Dialog.confirm({
      content: `确认删除「${location.name}」及备注等信息？不可恢复。`,
      confirmText: '确定',
      cancelText: '取消',
      onConfirm: async () => {
        try {
          await onDelete(location);
        } catch (err: unknown) {
          console.error('[Travel] 删除位置失败:', err, { locationId: location.id });
          if (err instanceof Error && err.stack) console.error(err.stack);
          Toast.show({ icon: 'fail', content: getErrorMessage(err, '删除失败') });
        }
      },
    });
  }

  return (
    <SwipeAction
      rightActions={[
        // 有精彩瞬间时隐藏切换按钮（状态锁定为已去）
        ...(hasMoments ? [] : [{
          key: 'toggle',
          text: location.checked ? '标记待去' : '标记已去',
          color: 'light' as const,
          onClick: handleToggle,
        }]),
        {
          key: 'delete',
          text: '删除',
          color: 'danger' as const,
          onClick: handleDelete,
        },
      ]}
    >
      <List.Item
        prefix={
          <CoverImage
            src={iconUrl}
            alt={location.name}
            width={44}
            height={44}
            shape="circle"
          />
        }
        description={location.address}
        extra={<StatusTag checked={location.checked} />}
        onClick={() => { onClick(location); }}
      >
        {location.name}
      </List.Item>
    </SwipeAction>
  );
}

