/**
 * 精彩瞬间编辑弹窗 — 日期选择 + 文字内容，添加/编辑复用同一组件
 */

'use client';

import { Popup, Form, TextArea, Button, Toast, NavBar, DatePicker } from 'antd-mobile';
import dayjs from 'dayjs';
import { useState, useEffect } from 'react';

import type { Moment } from '../types';


// 将 "YYYY-MM-DD" 字符串转为 Date 对象
function dateStrToDate(str: string): Date {
  const d = dayjs(str);
  return d.isValid() ? d.toDate() : new Date();
}

// 将 Date 对象转为 "YYYY-MM-DD" 字符串
function dateToStr(d: Date): string {
  return dayjs(d).format('YYYY-MM-DD');
}

/**
 * 精彩瞬间编辑弹窗，添加/编辑复用同一组件
 *
 * 通过 moment prop 是否非空判断编辑模式。日期使用 antd-mobile DatePicker，
 * 值与 dayjs 互转。保存时分 add/save 两条路径。
 */
export function MomentEditPopup({
  moment,
  visible,
  onClose,
  onSave,
  onAdd,
}: {
  moment: Moment | null;
  visible: boolean;
  onClose: () => void;
  onSave: (id: string, data: { date: string; text: string }) => Promise<void>;
  onAdd: (data: { date: string; text: string }) => Promise<void>;
}) {
  const [date, setDate] = useState('');
  const [text, setText] = useState('');
  const [saving, setSaving] = useState(false);
  const [datePickerVisible, setDatePickerVisible] = useState(false);

  const isEdit = !!moment;

  useEffect(() => {
    if (visible) {
      if (moment) {
        setDate(moment.date);
        setText(moment.text);
      } else {
        setDate(new Date().toISOString().slice(0, 10));
        setText('');
      }
    }
  }, [visible, moment]);

  /**
   * 提交瞬间表单 —— 根据 isEdit 判断走 onSave（编辑）或 onAdd（新增）路径，
   * 先校验日期非空，成功后关闭弹窗，失败时打 ERROR 日志并 Toast 提示。
   */
  async function handleSave() {
    if (!date.trim()) {
      Toast.show({ icon: 'fail', content: '请选择日期' });
      return;
    }
    setSaving(true);
    try {
      if (isEdit && moment) {
        await onSave(moment.id, { date, text });
        Toast.show({ icon: 'success', content: '修改成功' });
      } else {
        await onAdd({ date, text });
        Toast.show({ icon: 'success', content: '添加成功' });
      }
      onClose();
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : '保存失败';
      console.error('[Travel] 保存瞬间失败:', err, { momentId: moment?.id });
      if (err instanceof Error && err.stack) console.error(err.stack);
      Toast.show({ icon: 'fail', content: message });
    } finally {
      setSaving(false);
    }
  }

  return (
    <Popup
      visible={visible}
      onMaskClick={onClose}
      onClose={onClose}
      position="bottom"
      bodyStyle={{
        borderTopLeftRadius: 16,
        borderTopRightRadius: 16,
        minHeight: '40vh',
        maxHeight: '75vh',
        overflow: 'auto',
      }}
    >
      <NavBar
        onBack={onClose}
        right={
          <Button color="primary" size="small" loading={saving} onClick={handleSave}>
            保存
          </Button>
        }
      >
        {isEdit ? '编辑瞬间' : '添加瞬间'}
      </NavBar>
      <Form layout="vertical" style={{ padding: '0 16px' }}>
        <Form.Item
          label="日期"
          onClick={() => { setDatePickerVisible(true); }}
        >
          <DatePicker
            visible={datePickerVisible}
            onClose={() => { setDatePickerVisible(false); }}
            value={dateStrToDate(date)}
            onConfirm={(val) => {
              if (val) setDate(dateToStr(val));
            }}
            min={new Date(2000, 0, 1)}
            max={new Date()}
          >
            {(value) => (value ? dateToStr(value) : '请选择日期')}
          </DatePicker>
        </Form.Item>
        <Form.Item label="内容">
          <TextArea
            value={text}
            onChange={setText}
            placeholder="记录这一刻..."
            rows={4}
          />
        </Form.Item>
      </Form>
    </Popup>
  );
}

/**
 * 搜索添加位置弹窗
 *
 * 调用高德地图 POI 搜索 API（services/amap.ts），展示搜索结果列表。
 */

'use client';

import { DotLoading, ErrorBlock, List, NavBar, Popup, SearchBar, Toast } from 'antd-mobile';
import { useState } from 'react';

import { searchPlace } from '../services/amap';

import type { AMapPoiItem } from '../services/amap';

/**
 * POI 搜索弹窗
 *
 * 调用高德地图 POI 搜索 API（services/amap.ts），展示搜索结果列表。
 * 点击结果项回调 onAdd 将选中地点添加到计划中。
 */
export function SearchPopup({
  visible,
  onClose,
  onAdd,
}: {
  visible: boolean;
  onClose: () => void;
  onAdd: (location: {
    name: string;
    address: string;
    longitude: number;
    latitude: number;
  }) => void;
}) {
  const [results, setResults] = useState<AMapPoiItem[]>([]);
  const [searching, setSearching] = useState(false);

  /**
   * 执行 POI 关键词搜索 —— 调用高德搜索 API，耗时 >500ms 时打 INFO 日志，
   * 失败时打 ERROR 日志并 Toast 提示。
   */
  async function handleSearch(keyword: string) {
    if (!keyword.trim()) return;
    setSearching(true);
    const startTime = Date.now();
    try {
      const items = await searchPlace(keyword);
      const elapsed = Date.now() - startTime;
      if (elapsed > 500) {
        console.info(`[Travel] POI 搜索耗时 ${String(elapsed)}ms, keyword=${keyword}, 结果数=${String(items.length)}`);
      }
      setResults(items);
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : '搜索失败';
      console.error('[Travel] POI 搜索失败:', err, { keyword });
      if (err instanceof Error && err.stack) console.error(err.stack);
      Toast.show({ icon: 'fail', content: '搜索失败: ' + message });
    } finally {
      setSearching(false);
    }
  }

  return (
    <Popup
      visible={visible}
      onMaskClick={onClose}
      onClose={onClose}
      position="bottom"
      bodyStyle={{
        borderTopLeftRadius: 16,
        borderTopRightRadius: 16,
        minHeight: '60vh',
        maxHeight: '75vh',
        overflow: 'auto',
      }}
    >
      <NavBar onBack={onClose}>添加位置</NavBar>
      <SearchBar placeholder="选择位置" onSearch={handleSearch} />
      {searching ? (
        <List>
          <List.Item prefix={<DotLoading />}>搜索中</List.Item>
        </List>
      ) : results.length === 0 ? (
        <ErrorBlock status="empty" title="暂无搜索结果" />
      ) : (
        <List>
          {results.map((item) => (
            <List.Item
              key={item.id}
              description={item.address}
              clickable
              onClick={() =>
              { onAdd({
                name: item.name,
                address: item.address,
                longitude: item.longitude,
                latitude: item.latitude,
              }); }
              }
            >
              {item.name}
            </List.Item>
          ))}
        </List>
      )}
    </Popup>
  );
}

/**
 * 图片上传组件
 *
 * 通过 OSS 签名 URL 直传，参考 TencentOss.getSignedPutUrl() 流程：
 * 1. 调用 Server Action 获取 COS 预签名 PUT URL
 * 2. 前端使用 fetch PUT 直传文件到 COS
 * 3. 上传成功后刷新签名 URL 显示预览
 *
 * 下载流程参考 TencentOss.getSignedUrl()：
 * - 通过 Server Action getImageUrl() 获取签名 URL
 * - 签名 URL 由 OssAdapter.getSignedUrl() 生成，包含临时访问凭据
 *
 * 仅允许 image/jpeg 格式上传。
 */

'use client';

import { Button, Space, Toast } from 'antd-mobile';
import { CameraOutline } from 'antd-mobile-icons';
import { useEffect, useRef, useState } from 'react';

import { getImageUrl, getUploadUrl } from '../actions';
export function UploadImage({
  locationId,
  type = 'cover',
  onSuccess,
}: {
  locationId: string;
  type?: 'cover' | 'icon';
  onSuccess?: () => void;
}) {
  const [uploading, setUploading] = useState(false);
  const [_previewUrl, setPreviewUrl] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    async function loadPreview() {
      try {
        const url = await getImageUrl(locationId, type);
        setPreviewUrl(url);
      } catch {
        // 预览加载失败不阻塞 UI，静默降级
        setPreviewUrl(null);
      }
    }
    loadPreview();
  }, [locationId, type]);

  function handleFileChange(event: React.ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0];
    if (file) {
      handleUpload(file);
    }
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  }

  /**
   * 三阶段上传流程：
   * 1. 调用 Server Action getUploadUrl 获取 COS 预签名 PUT URL
   * 2. 使用 fetch PUT 直传文件到 COS（仅支持 image/jpeg）
   * 3. 调用 getImageUrl 刷新预览并回调 onSuccess
   * 各阶段耗时 >500ms 时打 INFO 日志，失败时打 ERROR 日志并 Toast。
   */
  async function handleUpload(file: File) {
    // 仅允许 JPG 格式
    if (!file.type.startsWith('image/jpeg')) {
      Toast.show({ icon: 'fail', content: '仅支持 JPG 格式图片' });
      return;
    }

    setUploading(true);
    const startTime = Date.now();
    try {
      const signedUrl = await getUploadUrl(locationId, type);
      const fetchStart = Date.now();
      const response = await fetch(signedUrl, {
        method: 'PUT',
        headers: {
          'Content-Type': file.type || 'application/octet-stream',
        },
        body: file,
      });
      const fetchElapsed = Date.now() - fetchStart;

      if (!response.ok) {
        throw new Error(`上传失败: ${String(response.status)} ${response.statusText}`);
      }
      if (fetchElapsed > 500) {
        console.info(`[Travel] COS 上传耗时 ${String(fetchElapsed)}ms, locationId=${locationId}, type=${type}, size=${String(file.size)}`);
      }

      const downloadUrl = await getImageUrl(locationId, type);
      setPreviewUrl(downloadUrl);
      onSuccess?.();
      Toast.show({ icon: 'success', content: '上传成功' });
      const totalElapsed = Date.now() - startTime;
      if (totalElapsed > 500) {
        console.info(`[Travel] 图片上传总耗时 ${String(totalElapsed)}ms, locationId=${locationId}, type=${type}`);
      }
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : '上传失败';
      console.error('[Travel] 图片上传失败:', err, { locationId, type, fileName: file.name });
      if (err instanceof Error && err.stack) console.error(err.stack);
      Toast.show({ icon: 'fail', content: '上传失败: ' + message });
    } finally {
      setUploading(false);
    }
  }

  return (
    <Space align="center">
      <input
        ref={fileInputRef}
        type="file"
        accept=".jpg,.jpeg"
        style={{ display: 'none' }}
        onChange={handleFileChange}
      />
      <Button
        onClick={() => fileInputRef.current?.click()}
        loading={uploading}
        shape="rounded"
        fill="outline"
      >
        <CameraOutline />
      </Button>
    </Space>
  );
}

/**
 * 旅行位置数据 Hook + Context
 *
 * useLocations 提供位置的增删改查 + 过滤 + 统计。
 * TravelContext 在 layout 层注入，子组件通过 useTravelContext 消费。
 */

'use client';

import { createContext, useContext, useState, useEffect, useCallback } from 'react';

import { fetchLocations, createLocation, editLocation, removeLocation } from '../actions';

import type { Location, Summary } from '../types';

/** 注入到 TravelContext 的数据类型 */
export type TravelData = {
  locations: Location[];
  sortedLocations: Location[];
  summary: Summary;
  loading: boolean;
  add: (data: { name: string; address: string; longitude: number; latitude: number; comments?: string }) => Promise<Location>;
  update: (id: string, data: Partial<Location>) => Promise<Location>;
  remove: (id: string) => Promise<void>;
  load: () => Promise<void>;
};

export const TravelContext = createContext<TravelData | null>(null);

/** 从 Context 获取旅行数据（必须在 TravelContext.Provider 内使用） */
export function useTravelContext() {
  const ctx = useContext(TravelContext);
  if (!ctx) throw new Error('useTravelContext must be used within TravelContext.Provider');
  return ctx;
}

/**
 * 位置数据管理 Hook
 *
 * 管理位置列表的全量数据、加载状态、CRUD 操作及过滤统计。
 * 采用乐观更新策略：add/update 成功后直接更新本地状态，remove 使用软删除（标记 deleted: true）。
 * 过滤逻辑基于未删除项，按 filter 参数筛出已勾选/未勾选/全部。
 */
export function useLocations(filter?: 'all' | 'checked' | 'uncheck') {
  const [allLocations, setAllLocations] = useState<Location[]>([]);
  const [loading, setLoading] = useState(false);

  /** 加载全量位置数据，更新本地状态 */
  const load = useCallback(async () => {
    setLoading(true);
    try {
      if (process.env.NODE_ENV !== 'production') console.debug('[Travel] 加载位置列表...');
      const t0 = Date.now();
      const data = await fetchLocations();
      const elapsed = Date.now() - t0;
      if (elapsed > 500) console.info(`[Travel] 加载位置列表耗时 ${String(elapsed)}ms`);
      setAllLocations(data);
    } catch (err) {
      /** ERROR: 加载位置数据失败，打印上下文帮助排查（COS 连接、权限等） */
      console.error('[Travel] 加载位置失败:', err);
      if (err instanceof Error && err.stack) console.error(err.stack);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  /** 新增位置：调用 Server Action 后追加到本地列表（乐观更新） */
  const add = useCallback(async (data: { name: string; address: string; longitude: number; latitude: number; comments?: string }) => {
    console.info('[Travel] 新增位置:', data.name);
    if (process.env.NODE_ENV !== 'production') console.debug('[Travel] createLocation 参数:', JSON.stringify(data));
    const t0 = Date.now();
    try {
      const newLoc = await createLocation(data);
      const elapsed = Date.now() - t0;
      if (elapsed > 500) console.info(`[Travel] 新增位置耗时 ${String(elapsed)}ms`);
      setAllLocations((prev) => [...prev, newLoc]);
      return newLoc;
    } catch (err) {
      console.error('[Travel] 新增位置失败:', { name: data.name, error: err });
      if (err instanceof Error && err.stack) console.error(err.stack);
      throw err;
    }
  }, []);

  /** 编辑位置：调用 Server Action 后替换本地列表中对应项 */
  const update = useCallback(async (id: string, data: Partial<Location>) => {
    console.info('[Travel] 编辑位置:', id);
    if (process.env.NODE_ENV !== 'production') console.debug('[Travel] editLocation 参数:', id, JSON.stringify(data));
    const t0 = Date.now();
    try {
      const updated = await editLocation(id, data);
      const elapsed = Date.now() - t0;
      if (elapsed > 500) console.info(`[Travel] 编辑位置耗时 ${String(elapsed)}ms`);
      setAllLocations((prev) => prev.map((l) => (l.id === id ? updated : l)));
      return updated;
    } catch (err) {
      console.error('[Travel] 编辑位置失败:', { id, error: err });
      if (err instanceof Error && err.stack) console.error(err.stack);
      throw err;
    }
  }, []);

  /** 软删除位置：调用 Server Action 后将本地副本标记为 deleted，避免数据丢失 */
  const remove = useCallback(async (id: string) => {
    console.info('[Travel] 删除位置:', id);
    if (process.env.NODE_ENV !== 'production') console.debug('[Travel] removeLocation 参数:', id);
    const t0 = Date.now();
    try {
      await removeLocation(id);
      const elapsed = Date.now() - t0;
      if (elapsed > 500) console.info(`[Travel] 删除位置耗时 ${String(elapsed)}ms`);
      /** 软删除而非从列表移除，保留数据可恢复 */
      setAllLocations((prev) => prev.map((l) => (l.id === id ? { ...l, deleted: true } : l)));
    } catch (err) {
      console.error('[Travel] 删除位置失败:', { id, error: err });
      if (err instanceof Error && err.stack) console.error(err.stack);
      throw err;
    }
  }, []);

  /** 过滤后的列表：先剔除已删除项，再按勾选状态筛选 */
  if (process.env.NODE_ENV !== 'production') console.debug(`[Travel] 位置过滤: filter=${String(filter)}, total=${String(allLocations.length)}`);
  const filteredLocations = allLocations
    .filter((loc) => !loc.deleted)
    .filter((loc) => {
      if (filter === 'checked') return loc.checked;       // 仅已勾选
      if (filter === 'uncheck') return !loc.checked;      // 仅未勾选
      return true;                                        // 全部（不含已删除）
    });

  /** 统计基于所有未删除的位置（与 summary 口径一致） */
  const activeLocations = allLocations.filter((l) => !l.deleted);
  const summary: Summary = {
    uncheckCount: activeLocations.filter((l) => !l.checked).length,
    uncheckPercentage: 0,
    checkedCount: activeLocations.filter((l) => l.checked).length,
    checkedPercentage: 0,
    count: activeLocations.length,
  };
  if (summary.count > 0) {
    summary.uncheckPercentage = Math.floor((summary.uncheckCount / summary.count) * 100);
    summary.checkedPercentage = Math.floor((summary.checkedCount / summary.count) * 100);
  }

  return {
    locations: allLocations,
    sortedLocations: filteredLocations,
    summary,
    loading,
    load,
    add,
    update,
    remove,
  };
}

/**
 * 精彩瞬间数据管理 Hook
 *
 * 精彩瞬间以嵌套 JSON 对象存储在位置的 moments 字段中，
 * 加载时从 fetchLocations 获取全量位置后再提取目标位置的 moments。
 * 操作完成后自动重新加载数据以保持与服务端同步。
 */

'use client';

import { useState, useEffect, useCallback } from 'react';

import { fetchLocations } from '../actions';
import { createMoment, editMoment, removeMoment } from '../actions';

import type { Moment } from '../types';

/** 管理指定位置的精彩瞬间列表 */
export function useMoments(locationId: string) {
  const [moments, setMoments] = useState<Moment[]>([]);
  const [loading, setLoading] = useState(false);

  /**
   * 加载指定位置的精彩瞬间列表
   *
   * 从全量位置数据中提取目标位置的 moments 嵌套对象，
   * 将其按日期降序排列后写入状态。
   */
  const load = useCallback(async () => {
    setLoading(true);
    try {
      const locations = await fetchLocations();
      const location = locations.find((l) => l.id === locationId);
      if (location?.moments) {
        const momentsMap = location.moments;
        const items: Moment[] = Object.entries(momentsMap).map(([id, m]) => ({
          id,
          locationId,
          date: m.date,
          text: m.text,
          createdTime: '',
        }));
        // 按日期降序排列，最近的在前
        items.sort((a, b) => b.date.localeCompare(a.date));
        setMoments(items);
      } else {
        setMoments([]);
      }
    } catch (err) {
      console.error('[Travel] useMoments.load 失败:', { locationId, error: err });
      if (err instanceof Error && err.stack) console.error(err.stack);
    } finally {
      setLoading(false);
    }
  }, [locationId]);

  useEffect(() => {
    load();
  }, [load]);

  /**
   * 新增精彩瞬间
   *
   * 调用 Server Action 创建后重新加载列表以同步。
   */
  const add = useCallback(async (data: { date: string; text: string }) => {
    try {
      await createMoment(locationId, data);
      await load();
    } catch (err) {
      console.error('[Travel] useMoments.add 失败:', { locationId, error: err });
      if (err instanceof Error && err.stack) console.error(err.stack);
      throw err;
    }
  }, [locationId, load]);

  /**
   * 编辑精彩瞬间
   *
   * 调用 Server Action 更新后重新加载列表以同步。
   */
  const update = useCallback(async (id: string, data: { date?: string; text?: string }) => {
    try {
      await editMoment(locationId, id, data);
      await load();
    } catch (err) {
      console.error('[Travel] useMoments.update 失败:', { locationId, momentId: id, error: err });
      if (err instanceof Error && err.stack) console.error(err.stack);
      throw err;
    }
  }, [locationId, load]);

  /**
   * 删除精彩瞬间
   *
   * 调用 Server Action 删除后重新加载列表以同步。
   */
  const remove = useCallback(async (id: string) => {
    try {
      await removeMoment(locationId, id);
      await load();
    } catch (err) {
      console.error('[Travel] useMoments.remove 失败:', { locationId, momentId: id, error: err });
      if (err instanceof Error && err.stack) console.error(err.stack);
      throw err;
    }
  }, [locationId, load]);

  return { moments, loading, load, add, update, remove };
}

/**
 * 旅行计划列表页
 *
 * 以列表形式展示位置，支持搜索过滤、下拉刷新。
 * 切换"待去→已去"时自动创建一条当天日期的精彩瞬间记录。
 * 有精彩瞬间的位置锁定为"已去"状态，不可回退。
 */

'use client';

import { PullToRefresh, List, DotLoading, ErrorBlock, Toast, SearchBar } from 'antd-mobile';
import { useState, useEffect, useMemo } from 'react';

import { createMoment } from '../actions';
import { LocationEditPopup } from '../components/location-edit-popup';
import { LocationListItem } from '../components/location-list-item';
import { LocationViewPopup } from '../components/location-view-popup';
import { MomentEditPopup } from '../components/moment-edit-popup';
import { SearchPopup } from '../components/search-popup';
import { useTravelContext } from '../hooks/use-locations';
import { useMoments } from '../hooks/use-moments';
import { filterLocations } from '../lib/filter-locations';

import type { Location, Moment } from '../types';

export default function LocationListPage() {
  const { sortedLocations, loading, add, update, remove, load } =
    useTravelContext();

  // 搜索状态
  const [searchText, setSearchText] = useState('');

  // 对已筛选列表做二次搜索过滤
  const filteredLocations = useMemo(
    () => filterLocations(sortedLocations, searchText),
    [sortedLocations, searchText],
  );

  // Popup 状态
  const [viewLocation, setViewLocation] = useState<Location | null>(null);
  const [editLocation, setEditLocation] = useState<Location | null>(null);
  const [editMoment, setEditMoment] = useState<{
    locationId: string;
    moment: Moment | null;
  } | null>(null);
  const [searchVisible, setSearchVisible] = useState(false);

  // 当前查看位置的精彩瞬间
  const {
    moments,
    add: addMoment,
    update: updateMoment,
    remove: removeMoment,
  } = useMoments(viewLocation?.id || '');

  // 监听 layout 触发的 open-search 事件
  useEffect(() => {
    function onOpenSearch() {
      setSearchVisible(true);
    }
    window.addEventListener('travel:open-search', onOpenSearch);
    return () => { window.removeEventListener('travel:open-search', onOpenSearch); };
  }, []);

  // ── 列表操作 ──

  /**
   * 判断位置是否有精彩瞬间记录
   *
   * 有记录的位置锁定为"已去"状态，UI 上禁用切换按钮。
   * 通过检查 moments 对象是否有键来判断（而非检查数组长度），避免空对象误判。
   */
  function hasMoments(location: Location): boolean {
    const moments = location.moments;
    return !!moments && Object.keys(moments).length > 0;
  }

  /**
   * 提取错误消息
   *
   * 优先使用 Error.message，类型不确定时回退到预设文案。
   */
  function getErrorMessage(err: unknown, fallback: string): string {
    if (err instanceof Error) return err.message || fallback;
    return fallback;
  }

  /**
   * 切换位置打卡状态
   *
   * 从"待去"切到"已去"时自动创建一条当天日期的空文本精彩瞬间记录，
   * 确保每个已去位置至少有一笔记录。有精彩瞬间的位置锁定为已去状态，不可回退。
   * 创建记录失败时中断切换，保持原状态。
   */
  async function handleToggle(location: Location) {
    // 有精彩瞬间时状态锁定，不可切换（防御性，UI 已禁用不会触发）
    if (hasMoments(location)) return;

    // 从待去切到已去时，自动创建一条当天日期的空文本精彩瞬间
    if (!location.checked) {
      try {
        await createMoment(location.id, {
          date: new Date().toISOString().slice(0, 10),
          text: '',
        });
      } catch (err: unknown) {
        console.error('[Travel] handleToggle 创建精彩瞬间失败', {
          locationId: location.id,
          error: err,
        });
        Toast.show({ icon: 'fail', content: getErrorMessage(err, '创建记录失败') });
        return; // 创建失败则不切换状态
      }
    }

    await update(location.id, { checked: !location.checked });
    const updated = { ...location, checked: !location.checked };
    if (viewLocation?.id === location.id) setViewLocation(updated);
    if (editLocation?.id === location.id) setEditLocation(updated);

    // 刷新列表数据（moments 变更后需要更新 hasMoments 判断）
    await load();
  }

  /** 删除位置（软删除），同时关闭该位置的查看弹窗 */
  async function handleDelete(location: Location) {
    await remove(location.id);
    if (viewLocation?.id === location.id) setViewLocation(null);
  }

  // ── 搜索添加 ──

  /**
   * 从搜索结果中添加新位置
   *
   * 创建成功后关闭搜索弹窗并打开该位置的查看弹窗。
   */
  async function handleAdd(data: {
    name: string;
    address: string;
    longitude: number;
    latitude: number;
  }) {
    const newLoc = await add(data);
    setSearchVisible(false);
    setViewLocation(newLoc);
  }

  // ── 渲染 ──

  return (
    <>
      {/* 搜索框 — 始终渲染在顶部 */}
      <SearchBar
        placeholder="搜索名称、地址、备注"
        value={searchText}
        onChange={setSearchText}
        onClear={() => { setSearchText(''); }}
      />

      {loading && sortedLocations.length === 0 ? (
        <List>
          <List.Item prefix={<DotLoading />}>加载中</List.Item>
        </List>
      ) : sortedLocations.length === 0 ? (
        <ErrorBlock status="empty" title="暂无位置" />
      ) : searchText.trim() && filteredLocations.length === 0 ? (
        <ErrorBlock status="empty" title="暂无搜索结果" />
      ) : (
        <PullToRefresh onRefresh={load}>
          <List>
            {filteredLocations.map((location) => (
              <LocationListItem
                key={location.id}
                location={location}
                hasMoments={hasMoments(location)}
                onClick={setViewLocation}
                onToggle={handleToggle}
                onDelete={handleDelete}
              />
            ))}
          </List>
        </PullToRefresh>
      )}

      <LocationViewPopup
        location={viewLocation}
        visible={!!viewLocation && !editMoment && !editLocation}
        onClose={() => { setViewLocation(null); }}
        moments={moments}
        onEdit={(loc) => { setEditLocation(loc); }}
        onToggle={handleToggle}
        onDelete={handleDelete}
        onAddMoment={() => {
          // eslint-disable-next-line @typescript-eslint/no-non-null-assertion -- viewLocation 由 visible 条件保证非空
          setEditMoment({ locationId: viewLocation!.id, moment: null });
        }}
        onEditMoment={(m) => {
          // eslint-disable-next-line @typescript-eslint/no-non-null-assertion -- viewLocation 由 visible 条件保证非空
          setEditMoment({ locationId: viewLocation!.id, moment: m });
        }}
        onDeleteMoment={async (m) => {
          await removeMoment(m.id);
        }}
      />

      <LocationEditPopup
        location={editLocation}
        visible={!!editLocation}
        onClose={() => { setEditLocation(null); }}
        onSave={update}
      />

      <MomentEditPopup
        moment={editMoment?.moment || null}
        visible={!!editMoment}
        onClose={() => { setEditMoment(null); }}
        onSave={updateMoment}
        onAdd={addMoment}
      />

      <SearchPopup
        visible={searchVisible}
        onClose={() => { setSearchVisible(false); }}
        onAdd={handleAdd}
      />
    </>
  );
}

/**
 * 旅行计划地图页
 *
 * 以高德地图为主视图，展示所有位置标记。
 * 点击标记弹出详情（LocationViewPopup），支持编辑、切换状态、删除。
 * 通过自定义事件 "travel:open-search" 触发搜索弹窗。
 */

'use client';

import { useRouter } from 'next/navigation';
import { useCallback, useRef, useState, useEffect } from 'react';

import { LocationEditPopup } from './components/location-edit-popup';
import { LocationViewPopup } from './components/location-view-popup';
import { MomentEditPopup } from './components/moment-edit-popup';
import { SearchPopup } from './components/search-popup';
import { TripMap } from './components/trip-map';
import { useTravelContext } from './hooks/use-locations';
import { useMoments } from './hooks/use-moments';
import { getCurrentPosition } from './services/amap';

import type { Location, Moment } from './types';

export default function TravelPage() {
  const router = useRouter();
  const { sortedLocations, add, update, remove } = useTravelContext();

  const [viewLocation, setViewLocation] = useState<Location | null>(null);
  const [editLocation, setEditLocation] = useState<Location | null>(null);
  const [editMoment, setEditMoment] = useState<{
    locationId: string;
    moment: Moment | null;
  } | null>(null);
  const [searchVisible, setSearchVisible] = useState(false);
  const mapRef = useRef<{ setCenter: (pos: [number, number]) => void }>(null);

  const {
    moments,
    add: addMoment,
    update: updateMoment,
    remove: removeMoment,
  } = useMoments(viewLocation?.id || '');

  // 监听 layout 触发的 open-search 事件
  useEffect(() => {
    function onOpenSearch() {
      setSearchVisible(true);
    }
    window.addEventListener('travel:open-search', onOpenSearch);
    return () => { window.removeEventListener('travel:open-search', onOpenSearch); };
  }, []);

  // 监听 "我的位置" 跳转
  useEffect(() => {
    const url = new URL(window.location.href);
    if (url.searchParams.get('center') === 'my-location') {
      getCurrentPosition()
        .then(([lng, lat]) => {
          if (mapRef.current) {
            mapRef.current.setCenter([lng, lat]);
          }
        })
        .catch((err: unknown) => {
          // WARN：GPS 定位不可用（用户拒绝授权或设备不支持），地图仍可正常使用
          console.warn('[Travel] 获取当前位置失败', err);
        });
      // 清除 query 参数
      router.replace('/travel');
    }
  }, [router]);

  const onMarkerClick = useCallback((location: Location) => {
    setViewLocation(location);
  }, []);

  /**
   * 切换位置打卡状态
   *
   * 更新后同步刷新当前打开的查看/编辑弹窗中的位置数据。
   */
  async function handleToggle(location: Location) {
    await update(location.id, { checked: !location.checked });
    const updated = { ...location, checked: !location.checked };
    if (viewLocation?.id === location.id) setViewLocation(updated);
    if (editLocation?.id === location.id) setEditLocation(updated);
  }

  /** 删除位置（软删除），同时关闭该位置的查看弹窗 */
  async function handleDelete(location: Location) {
    await remove(location.id);
    if (viewLocation?.id === location.id) setViewLocation(null);
  }

  /**
   * 从搜索结果中添加新位置
   *
   * 创建成功后关闭搜索弹窗并直接打开该位置的查看弹窗。
   */
  async function handleAdd(data: {
    name: string;
    address: string;
    longitude: number;
    latitude: number;
  }) {
    const newLoc = await add(data);
    setSearchVisible(false);
    setViewLocation(newLoc);
  }

  return (
    <div style={{ position: 'relative', height: '100%', display: 'flex', flexDirection: 'column' }}>
      <TripMap
        ref={mapRef}
        locations={sortedLocations}
        onMarkerClick={onMarkerClick}
        style={{ flex: 1 }}
      />

      <LocationViewPopup
        location={viewLocation}
        visible={!!viewLocation}
        onClose={() => { setViewLocation(null); }}
        moments={moments}
        onEdit={(loc) => { setEditLocation(loc); }}
        onToggle={handleToggle}
        onDelete={handleDelete}
        onAddMoment={() => {
          // eslint-disable-next-line @typescript-eslint/no-non-null-assertion -- viewLocation 由 visible 条件保证非空
          setEditMoment({ locationId: viewLocation!.id, moment: null });
        }}
        onEditMoment={(m) => {
          // eslint-disable-next-line @typescript-eslint/no-non-null-assertion -- viewLocation 由 visible 条件保证非空
          setEditMoment({ locationId: viewLocation!.id, moment: m });
        }}
        onDeleteMoment={async (m) => { await removeMoment(m.id); }}
      />

      <LocationEditPopup
        location={editLocation}
        visible={!!editLocation}
        onClose={() => { setEditLocation(null); }}
        onSave={update}
      />

      <MomentEditPopup
        moment={editMoment?.moment || null}
        visible={!!editMoment}
        onClose={() => { setEditMoment(null); }}
        onSave={updateMoment}
        onAdd={addMoment}
      />

      <SearchPopup
        visible={searchVisible}
        onClose={() => { setSearchVisible(false); }}
        onAdd={handleAdd}
      />
    </div>
  );
}

import { getOssAdapter, isOssConfigured } from '@/lib/oss';
import type { OssPutOptions } from '@/lib/oss';
import { newId, formatDateTime } from '@/lib/utils';

import type { Location } from '../types';

/**
 * 旅行模块 OSS 存储路径约定
 * - 位置数据: apps/travel/locations.json
 * - 图片统一: apps/travel/posters/{id}.jpg
 *
 * 访问 URL 格式（COS CI 样式处理）：
 * - https://{bucket}.cos.{region}.myqcloud.com/apps/travel/posters/{id}.jpg/{stylename}
 * - stylename: cover | icon
 */

const LOCATIONS_KEY = process.env.OSS_TRAVEL_LOCATIONS_KEY || 'apps/travel/locations.json';
const POSTERS_PREFIX = process.env.OSS_TRAVEL_POSTERS_PREFIX || 'apps/travel/posters';


/**
 * 构造 OSS 公共访问基础 URL
 *
 * 格式：https://{bucket}.cos.{region}.myqcloud.com
 * 用于拼接带 COS CI 样式后缀的图片访问地址。
 */
function getOssBaseUrl(): string {
  const adapter = getOssAdapter();
  return `https://${adapter.getBucket()}.cos.${adapter.getEndpoint()}.myqcloud.com`;
}

// ─── OSS 通用操作（通过 OssAdapter 适配器） ────────────────────────────

/**
 * 获取文件内容
 *
 * 通过 OssAdapter.getString() 读取，参考 TencentOss.getString()
 */
async function ossGetString(key: string): Promise<string> {
  const adapter = getOssAdapter();
  return adapter.getString(key);
}

/**
 * 上传字符串内容
 *
 * 通过 OssAdapter.putString() 写入，参考 TencentOss.putString()
 */
async function ossPutString(key: string, content: string, options?: OssPutOptions): Promise<void> {
  const adapter = getOssAdapter();
  return adapter.putString(key, content, options);
}

/**
 * 删除文件
 *
 * 通过 OssAdapter.delete() 删除，参考 TencentOss.delete()
 */
async function ossDelete(key: string): Promise<void> {
  const adapter = getOssAdapter();
  return adapter.delete(key);
}

/**
 * 获取上传签名 URL
 *
 * 通过 OssAdapter.getSignedPutUrl() 获取，参考 TencentOss.getSignedPutUrl()
 * 用于前端直传（图片上传等）。
 */
async function ossGetSignedPutUrl(key: string, options?: OssPutOptions): Promise<string> {
  const adapter = getOssAdapter();
  return adapter.getSignedPutUrl(key, options);
}

// ─── 位置数据 CRUD ────────────────────────────────────────────────────

/**
 * 获取所有位置
 *
 * 从 OSS 的 apps/travel/locations.json 读取。
 * 文件不存在时返回空数组。
 */
export async function getLocations(): Promise<Location[]> {
  if (!isOssConfigured()) {
    return [];
  }
  try {
    const jsonStr = await ossGetString(LOCATIONS_KEY);
    return JSON.parse(jsonStr) as Location[];
  } catch {
    return [];
  }
}

/**
 * 保存所有位置
 *
 * 将位置数据写入 OSS 的 apps/travel/locations.json。
 */
async function saveLocations(locations: Location[]): Promise<void> {
  await ossPutString(LOCATIONS_KEY, JSON.stringify(locations), {
    headers: { 'Content-Type': 'application/json' },
  });
}

/**
 * 新增位置
 */
export async function addLocation(data: {
  name: string;
  address: string;
  longitude: number;
  latitude: number;
  comments?: string;
}): Promise<Location> {
  const locations = await getLocations();
  const location: Location = {
    id: newId(),
    name: data.name,
    address: data.address,
    longitude: data.longitude,
    latitude: data.latitude,
    checked: false,
    comments: data.comments || '',
    deleted: false,
    createdTime: formatDateTime(new Date()),
  };
  locations.push(location);
  await saveLocations(locations);
  return location;
}

/**
 * 更新位置
 */
export async function updateLocation(
  id: string,
  data: Partial<Location>,
): Promise<Location> {
  const locations = await getLocations();
  const location = locations.find((l) => l.id === id);
  if (!location) throw new Error(`位置 ${id} 不存在`);

  if (data.name !== undefined) location.name = data.name;
  if (data.address !== undefined) location.address = data.address;
  if (data.comments !== undefined) location.comments = data.comments;
  if (data.checked !== undefined) location.checked = data.checked;
  if (data.longitude !== undefined) location.longitude = data.longitude;
  if (data.latitude !== undefined) location.latitude = data.latitude;

  await saveLocations(locations);
  return location;
}

/**
 * 删除位置（软删除）
 *
 * 将 deleted 标记设为 true，并尝试删除封面图。
 */
export async function deleteLocation(id: string): Promise<void> {
  const locations = await getLocations();
  const location = locations.find((l) => l.id === id);
  if (!location) throw new Error(`位置 ${id} 不存在`);

  location.deleted = true;
  await saveLocations(locations);

  // 删除封面图（忽略不存在的情况）
  try {
    await ossDelete(`${POSTERS_PREFIX}/${id}.jpg`);
  } catch {
    // 封面图可能不存在，忽略
  }
}

// ─── 精彩瞬间 ──────────────────────────────────────────────────────────

/**
 * 新增瞬间
 */
export async function addMoment(
  locationId: string,
  data: { date: string; text: string },
): Promise<Location> {
  const locations = await getLocations();
  const location = locations.find((l) => l.id === locationId);
  if (!location) throw new Error(`位置 ${locationId} 不存在`);

  // 位置上的 moments 存储（用 Record 结构与旧项目一致）
  const moments = location.moments || {};
  const momentId = newId();
  moments[momentId] = { date: data.date, text: data.text };
  location.moments = moments;

  await saveLocations(locations);
  return location;
}

/**
 * 更新瞬间
 */
export async function updateMoment(
  locationId: string,
  momentId: string,
  data: { date?: string; text?: string },
): Promise<Location> {
  const locations = await getLocations();
  const location = locations.find((l) => l.id === locationId);
  if (!location) throw new Error(`位置 ${locationId} 不存在`);

  const moments = location.moments;
  if (!moments || !moments[momentId]) {
    throw new Error(`瞬间 ${momentId} 不存在`);
  }

  if (data.date !== undefined) moments[momentId].date = data.date;
  if (data.text !== undefined) moments[momentId].text = data.text;

  await saveLocations(locations);
  return location;
}

/**
 * 删除瞬间
 */
export async function deleteMoment(
  locationId: string,
  momentId: string,
): Promise<Location> {
  const locations = await getLocations();
  const location = locations.find((l) => l.id === locationId);
  if (!location) throw new Error(`位置 ${locationId} 不存在`);

  const moments = location.moments;
  if (moments && moments[momentId]) {
    delete moments[momentId];
  }

  await saveLocations(locations);
  return location;
}

// ─── 图片上传 / 访问 ────────────────────────────────────────────────────

/**
 * 获取 poster 上传签名 URL
 *
 * 前端拿到签名 URL 后直接 PUT 上传图片到 COS。
 * 所有图片（封面/图标）统一上传到 apps/travel/posters/{id}.jpg。
 */
export async function getPosterUploadUrl(id: string): Promise<string> {
  return ossGetSignedPutUrl(`${POSTERS_PREFIX}/${id}.jpg`);
}

/**
 * 获取 poster 访问 URL（COS CI 样式处理）
 *
 * 通过 URL 后缀指定 COS CI 处理样式，格式：
 * https://{bucket}.cos.{region}.myqcloud.com/apps/travel/posters/{id}.jpg/{stylename}
 *
 * @param id - 图片标识
 * @param stylename - 样式名：cover | icon
 */
export function getPosterStyledUrl(id: string, stylename: 'cover' | 'icon'): string {
  return `${getOssBaseUrl()}/${POSTERS_PREFIX}/${id}.jpg/${stylename}`;
}

/**
 * GET /api/watering/get-state — 设备拉取状态 API
 *
 * ESP32 固件定期轮询此接口获取最新 switch 状态和 process 指令。
 * 通过比较 stateId 判断是否有变化，仅在有变化时下发 process 对象。
 * 同时刷新设备心跳时间。
 */

import { NextResponse } from 'next/server';

import { getDeviceState, getDeviceConfig, updateTick } from '@/app/watering/services/db';
import type { DeviceState, DeviceConfig } from '@/app/watering/types';

import type { NextRequest } from 'next/server';

/** 环境变量 */
const POLL_INTERVAL = parseInt(process.env.WATERING_POLL_INTERVAL || '15000');
const SLEEP_DURATION = parseInt(process.env.WATERING_SLEEP_DURATION || '300000');

/**
 * 构建精简的 get-state 响应（仅包含固件实际使用的字段）
 */
function buildResponse(
  state: DeviceState | null,
  changed: boolean,
  config: DeviceConfig | null,
  clientProcessesVersion?: string,
) {
  const result: Record<string, unknown> = {};

  // 始终包含 stateId
  result.stateId = state?.stateId || '';

  // 变化标志
  result.changed = changed;

  // switch 状态
  result.switch = state?.switch || 'off';

  // 轮询间隔
  result.sleep = POLL_INTERVAL;

  // 当前执行的流程（仅在变化时下发，避免重复传大对象）
  if (changed && state?.process) {
    result.process = state.process;
  }

  // 深度睡眠时长（仅无定时任务且无流程执行时下发）
  if (
    config &&
    (!config.schedules || config.schedules.length === 0) &&
    state?.switch !== 'on'
  ) {
    result.sleepDuration = SLEEP_DURATION;
  }

  // processes 版本控制下发
  if (config?.processesVersion) {
    result.processesVersion = config.processesVersion;
    // 仅在版本不匹配或首次下发时包含完整 processes 数据
    if (clientProcessesVersion !== config.processesVersion) {
      result.processes = config.processes;
    }
  }

  return result;
}

/**
 * GET /api/watering/get-state
 *
 * ESP32 固件轮询获取最新 switch 状态和 process 指令。
 * 通过 stateId 比较判断是否有变化，仅在有变化时下发 process 对象，减少传输量。
 * 同时刷新设备心跳，并下发 processes 版本用于增量同步配置。
 */
export async function GET(request: NextRequest) {
  const { searchParams } = request.nextUrl;
  const chipId = searchParams.get('chipId') || '';
  const macAddress = searchParams.get('macAddress') || '';
  const clientStateId = searchParams.get('stateId') || '';
  const clientProcessesVersion = searchParams.get('processesVersion') || '';

  console.info('[Watering] get-state 请求', { chipId, macAddress, clientStateId });

  if (!chipId || !macAddress) {
    console.warn('[Watering] get-state 缺少必要参数', { chipId, macAddress });
    return NextResponse.json({ error: 'chipId and macAddress required' }, { status: 400 });
  }

  try {
    // 刷新心跳
    await updateTick(chipId);

    // 并行读取状态和配置
    const [state, config] = await Promise.all([
      getDeviceState(chipId),
      getDeviceConfig(chipId),
    ]);

    // 比较是否有变化
    const changed = !state || clientStateId !== state.stateId;

    // 构建精简响应
    const response = buildResponse(state, changed, config, clientProcessesVersion);

    return NextResponse.json(response);
  } catch (err) {
    console.error('[Watering] get-state 处理失败', {
      chipId,
      macAddress,
      error: err instanceof Error ? err.message : String(err),
    });
    if (err instanceof Error && err.stack) console.error(err.stack);
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 });
  }
}

/**
 * 设备卡片组件 — 展示设备状态、在线信息、操作按钮（开关/配置/日志）
 */

'use client';

import {
  EditOutlined,
  FileTextOutlined,
  ThunderboltOutlined,
  PauseCircleOutlined,
  DeleteOutlined,
} from '@ant-design/icons';
import { Card, Tag, Button, Row, Col, message, Popconfirm } from 'antd';
import { useRouter } from 'next/navigation';

import { setDeviceSwitch, removeDevice } from '../actions';

import type { DeviceItem } from '../types';

export function DeviceCard({
  device,
  onRefresh,
}: {
  device: DeviceItem;
  onRefresh: () => void;
}) {
  const router = useRouter();

  /**
   * 电压计算
   *
   * 先从 sensors 中取原始 ADC 读数：
   * - 若配置了 voltage.sensor 则取对应引脚的传感器值
   * - 否则回退到 voltage_0 引脚
   *
   * 分压公式：V_actual = V_sensor × (R1 + R2) / R2
   * 仅在配置了分压电阻且 R1、R2 均 >0 时应用分压比修正；
   * 否则直接使用原始 ADC 读数（假设无分压电路）。
   */
  const rawVoltage = device.voltage?.sensor
    ? (device.state?.sensors?.[device.voltage.sensor])
    : (device.state?.sensors?.voltage_0);

  const voltage =
    typeof rawVoltage === 'number'
      ? device.voltage && device.voltage.r1 > 0 && device.voltage.r2 > 0
        ? rawVoltage * ((device.voltage.r1 + device.voltage.r2) / device.voltage.r2)
        : rawVoltage
      : undefined;

  const processes = device.processes || [];

  /**
   * 判断某流程是否正在执行
   *
   * 逻辑：
   * 1. 设备必须处于 on 状态
   * 2. 若设备上报了 state.index（当前执行流程索引），则直接比对
   * 3. 否则对比 bootExec（设备上报的是开机自动执行），用于离线/心跳未携带 index 的场景
   */
  function isExec(index: number): boolean {
    if (device.state?.switch === 'on') {
      if (typeof device.state.index === 'number') {
        return device.state.index === index;
      }
      // 设备未上报 index 时，用 bootExec 作为判断依据
      return device.bootExec === index;
    }
    return false;
  }

  /**
   * 执行或终止指定流程
   *
   * 逻辑：若流程正在执行（isExec 返回 true）则发送 off 终止，
   * 否则发送 on 启动。操作后刷新设备列表以同步前端状态。
   */
  async function onClickSwitch(index: number) {
    try {
      if (isExec(index)) {
        // 关闭
        await setDeviceSwitch(device.chipId, 'off', index);
        message.success(`已终止 ${processes[index]?.name ?? '未知'}`);
      } else {
        // 打开
        await setDeviceSwitch(device.chipId, 'on', index);
        message.success(`已执行 ${processes[index]?.name ?? '未知'}`);
      }
      onRefresh();
    } catch (err: unknown) {
      console.error(
        `[DeviceCard] 切换流程失败 chipId=${device.chipId} process=${String(processes[index]?.name)}`,
        err,
      );
      message.error(err instanceof Error ? err.message : String(err) || '操作失败');
    }
  }

  /** 清除设备状态（发送 off 指令） */
  async function onClickClear() {
    try {
      await setDeviceSwitch(device.chipId, 'off');
      message.success('已清除状态');
      onRefresh();
    } catch (err: unknown) {
      console.error(
        `[DeviceCard] 清除设备状态失败 chipId=${device.chipId}`,
        err,
      );
      message.error(err instanceof Error ? err.message : String(err) || '清除失败');
    }
  }

  /** 删除设备（调用 removeDevice action，不可恢复） */
  async function handleRemove() {
    try {
      await removeDevice(device.chipId);
      message.success('设备已删除');
      onRefresh();
    } catch (err: unknown) {
      console.error(
        `[DeviceCard] 删除设备失败 chipId=${device.chipId}`,
        err,
      );
      message.error(err instanceof Error ? err.message : String(err) || '删除失败');
    }
  }

  return (
    <Card
      size="small"
      title={device.name || `设备-${device.chipId}`}
      extra={
        <div style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
          <Button
            type="text"
            size="small"
            icon={<FileTextOutlined />}
            onClick={() =>
            { router.push(
              `/watering/logs/${device.chipId}?macAddress=${encodeURIComponent(device.macAddress)}`,
            ); }
            }
          >
            日志
          </Button>
          <Button
            type="text"
            size="small"
            icon={<EditOutlined />}
            onClick={() =>
            { router.push(
              `/watering/devices/${device.chipId}?macAddress=${encodeURIComponent(device.macAddress)}`,
            ); }
            }
          >
            配置
          </Button>
          <Popconfirm title="确认清除设备状态？" onConfirm={onClickClear}>
            <Button type="text" size="small" icon={<DeleteOutlined />} danger />
          </Popconfirm>
          <Popconfirm title="确认删除设备？不可恢复。" onConfirm={handleRemove}>
            <Button type="text" size="small" danger>
              删除
            </Button>
          </Popconfirm>
        </div>
      }
      style={{ marginBottom: 12 }}
    >
      {/* 设备信息 — 1 行 2 列 */}
      <Row gutter={[8, 4]} style={{ marginBottom: 8 }}>
        <Col span={12}>
          <span style={{ color: '#999', fontSize: 12 }}>芯片: </span>
          <span style={{ fontSize: 13 }}>{device.chipId}</span>
        </Col>
        {voltage !== undefined ? (
          <Col span={12}>
            <span style={{ color: '#999', fontSize: 12 }}>电压: </span>
            <span style={{ fontSize: 13, fontWeight: 500 }}>
              {voltage.toFixed(2)}V
            </span>
            {device.voltage && (
              <span style={{ fontSize: 10, color: '#bbb', marginLeft: 2 }}>
                (计算)
              </span>
            )}
          </Col>
        ) : (
          <Col span={12} />
        )}
        <Col span={12}>
          <span style={{ color: '#999', fontSize: 12 }}>网卡: </span>
          <span style={{ fontSize: 12 }}>{device.macAddress}</span>
        </Col>
        <Col span={12}>
          <span style={{ color: '#999', fontSize: 12 }}>状态: </span>
          {device.isOnline ? (
            <Tag color="green" style={{ margin: 0 }}>
              在线
            </Tag>
          ) : (
            <Tag color="default" style={{ margin: 0 }}>
              离线
            </Tag>
          )}
        </Col>
      </Row>

      {/*
         * 流程快捷按钮网格
         *
         * 布局算法：
         * - 偶数个流程：每行 2 列（span=12）
         * - 奇数个流程：第 1 个占整行（span=24），其余每行 2 列
         *
         * 按钮禁用条件：
         * 1. 设备离线 → 所有按钮不可用
         * 2. 设备开启了 idleSleep 且该流程未在执行 → 设备待机省电，不接受实时控制
         */}
      {processes.length > 0 && (
        <div style={{ marginTop: 8 }}>
          {(() => {
            // 计算每个按钮的栅格宽度
            const items: { idx: number; span: number }[] = [];
            if (processes.length % 2 === 1) {
              items.push({ idx: 0, span: 24 });
              for (let i = 1; i < processes.length; i++) {
                items.push({ idx: i, span: 12 });
              }
            } else {
              for (let i = 0; i < processes.length; i++) {
                items.push({ idx: i, span: 12 });
              }
            }
            // 将 items 按行分组：span=24 独占一行，否则两个一组
            const rows: { idx: number; span: number }[][] = [];
            let i = 0;
            while (i < items.length) {
              const item = items[i];
              if (!item) break;
              if (item.span === 24) {
                rows.push([item]);
                i++;
              } else {
                rows.push(items.slice(i, i + 2));
                i += 2;
              }
            }
            return rows.map((row, rowIdx) => (
              <Row gutter={8} key={rowIdx} style={{ marginBottom: 4 }}>
                {row.map(({ idx, span }) => {
                  const exec = isExec(idx);
                  // idleSleep 模式下仅允许终止正在执行的流程
                  const disabled = !device.isOnline || (!exec && !!device.idleSleep);
                  return (
                    <Col span={span} key={idx}>
                      <Button
                        type="primary"
                        danger={exec}
                        disabled={disabled}
                        block
                        size="small"
                        icon={
                          exec ? (
                            <PauseCircleOutlined />
                          ) : (
                            <ThunderboltOutlined />
                          )
                        }
                        onClick={() => onClickSwitch(idx)}
                      >
                        {exec ? '停止' : processes[idx]?.name ?? ''}
                      </Button>
                    </Col>
                  );
                })}
              </Row>
            ));
          })()}
        </div>
      )}

    </Card>
  );
}

