      </div>

      {/* ---- 流程表格（匹配 IeForm 的流程 el-table）---- */}
      <div style={{ marginBottom: 16 }}>
        <h4 style={{ margin: '0 0 8px', fontSize: 14 }}>功能</h4>
        <Table
          dataSource={form.processes}
          columns={processColumns}
          rowKey="key"
          pagination={false}
          size="small"
          bordered
        />
        <Button
          type="dashed"
          icon={<PlusOutlined />}
          onClick={addProcess}
          block
          style={{ marginTop: 8 }}
