          添加
        </Button>
      </div>

      {/* ---- 定时表格（匹配 IeForm 的定时 el-table）---- */}
      <div style={{ marginBottom: 16 }}>
        <h4 style={{ margin: '0 0 8px', fontSize: 14 }}>计划任务</h4>
        <Table
          dataSource={form.schedules}
          columns={scheduleColumns}
          rowKey="key"
          pagination={false}
          size="small"
          bordered
        />
        <Button
          type="dashed"
          icon={<PlusOutlined />}
          onClick={addSchedule}
          block
          style={{ marginTop: 8 }}
        >
          添加
        </Button>
      </div>

      {/* ============================================
          嵌套 Drawer 层（匹配 IotEditor 的嵌套 el-drawer）
          ============================================ */}

      {/* 流程编辑 Drawer (80%) */}
      <Drawer
        title="编辑流程"
        placement="bottom"
        size="80%"
        open={processVisible}
        onClose={() => { setProcessVisible(false); }}
        destroyOnHidden
        extra={
          <Space>
            <Popconfirm title="确认删除此流程？" onConfirm={deleteProcess}>
              <Button icon={<DeleteOutlined />} danger size="small">
                删除
              </Button>
            </Popconfirm>
            <Button
              icon={<CloseOutlined />}
              onClick={() => { setProcessVisible(false); }}
              size="small"
            >
              关闭
            </Button>
          </Space>
        }
      >
        {/* eslint-disable @typescript-eslint/no-non-null-assertion -- processIndex > -1 条件已保证 */}
        {processIndex > -1 && (
          <ProcessEditor
            process={form.processes[processIndex]!}
            gpio={gpio}
            onChange={(updated) => { updateProcess(processIndex, updated); }}
            onRemove={deleteProcess}
            onEditStep={(stepIdx) => {
              setStepIndex(stepIdx);
              setStepVisible(true);
            }}
            onAddStep={addStep}
          />
        )}
        {/* eslint-enable @typescript-eslint/no-non-null-assertion */}
      </Drawer>

      {/* 步骤编辑 Drawer (75%) */}
      <Drawer
        title="编辑步骤"
        placement="bottom"
        size="75%"
        open={stepVisible}
        onClose={() => { setStepVisible(false); }}
        destroyOnHidden
        extra={
          <Space>
            <Popconfirm title="确认删除此步骤？" onConfirm={deleteStep}>
              <Button icon={<DeleteOutlined />} danger size="small">
                删除
              </Button>
            </Popconfirm>
            <Button
              icon={<CloseOutlined />}
              onClick={() => { setStepVisible(false); }}
              size="small"
            >
              关闭
            </Button>
          </Space>
        }
      >
        {/* eslint-disable @typescript-eslint/no-non-null-assertion -- stepIndex > -1 && processIndex > -1 条件已保证 */}
        {stepIndex > -1 && processIndex > -1 && (
          <ProcessStepEditor
            step={form.processes[processIndex]!.steps[stepIndex]!}
            gpio={gpio}
            onChange={(updated) => { updateStep(stepIndex, updated); }}
            onRemove={deleteStep}
            onEditInterrupt={(intIdx) => {
              setInterruptIndex(intIdx);
              setInterruptVisible(true);
            }}
            onAddInterrupt={addInterrupt}
          />
        )}
        {/* eslint-enable @typescript-eslint/no-non-null-assertion */}
      </Drawer>

      {/* 中断编辑 Drawer (70%) */}
      <Drawer
        title="编辑中断"
        placement="bottom"
        size="70%"
        open={interruptVisible}
        onClose={() => { setInterruptVisible(false); }}
        destroyOnHidden
        extra={
          <Space>
            <Popconfirm title="确认删除此中断？" onConfirm={deleteInterrupt}>
              <Button icon={<DeleteOutlined />} danger size="small">
                删除
              </Button>
            </Popconfirm>
            <Button
              icon={<CloseOutlined />}
              onClick={() => { setInterruptVisible(false); }}
              size="small"
            >
              关闭
            </Button>
          </Space>
        }
      >
        {interruptIndex > -1 &&
          stepIndex > -1 &&
          processIndex > -1 &&
          /* eslint-disable @typescript-eslint/no-non-null-assertion -- interruptIndex/stepIndex/processIndex 三个条件已保证各级索引有效 */
          form.processes[processIndex]!.steps[stepIndex]!.interrupts && (
          <ProcessInterruptEditor
            interrupt={
              form.processes[processIndex]!.steps[stepIndex]!.interrupts[
                interruptIndex
              ]!
            }
            gpio={gpio}
            onChange={(updated) => { updateInterrupt(interruptIndex, updated); }}
            onRemove={deleteInterrupt}
          />
          /* eslint-enable @typescript-eslint/no-non-null-assertion */
        )}
      </Drawer>

      {/* 定时编辑 Drawer (70%) */}
      <Drawer
        title="编辑定时任务"
        placement="bottom"
        size="70%"
        open={scheduleVisible}
        onClose={() => { setScheduleVisible(false); }}
        destroyOnHidden
        extra={
          <Space>
            <Popconfirm title="确认删除此定时任务？" onConfirm={deleteSchedule}>
              <Button icon={<DeleteOutlined />} danger size="small">
                删除
              </Button>
            </Popconfirm>
            <Button
              icon={<CloseOutlined />}
              onClick={() => { setScheduleVisible(false); }}
              size="small"
            >
              关闭
            </Button>
          </Space>
        }
      >
        {/* eslint-disable @typescript-eslint/no-non-null-assertion -- scheduleIndex > -1 条件已保证 */}
        {scheduleIndex > -1 && (
          <ScheduleEditor
            schedules={[form.schedules[scheduleIndex]!]}
            processes={form.processes}
            onChange={(updated) => {
              if (updated.length > 0) {

                updateSchedule(scheduleIndex, updated[0]!);
              }
            }}
          />
        )}
        {/* eslint-enable @typescript-eslint/no-non-null-assertion */}
      </Drawer>

      {/* 电压检测配置 Drawer (60%) */}
      <VoltageConfigDrawer
        open={voltageVisible}
        voltage={form.voltage}
        sensors={gpio.sensors}
        onChange={(vc) => { setForm({ ...form, voltage: vc }); }}
        onClose={() => { setVoltageConfigVisible(false); }}
      />
    </div>
  );
}

/**
 * 日志查看器 — 按 stateId 分组展示 IoT 通信日志，支持耗时计算和格式化
 */

'use client';

import { Timeline, Tag, Divider } from 'antd';

const eventLabels: Record<string, string> = {
  bootstrap: '开机',
  execute: '执行',
  finish: '完成',
  terminate: '终止',
  change: '变更',
  heartbeat: '心跳',
  offline: '离线',
};

const eventColors: Record<string, string> = {
  bootstrap: 'green',
  execute: 'orange',
  finish: 'orange',
  terminate: 'orange',
  change: 'blue',
  heartbeat: 'default',
  offline: 'gray',
};

export type LogItem = {
  event: string;
  createdTime: string;
  state?: unknown;
  stateId?: string;
  message?: string;
  process?: { name?: string };
  cause?: string;
};

/** 按 stateId 分组，每组按时间排序（倒序：最新的 stateId 组在前，组内正序）*/
function groupByStateId(logs: LogItem[]): Array<{ stateId: string; items: LogItem[] }> {
  const map: Record<string, LogItem[]> = {};
  for (const log of logs) {
    const key = log.stateId || '_unknown';
    if (!map[key]) map[key] = [];
    map[key].push(log);
  }
  // 组内按时间正序
  for (const key of Object.keys(map)) {
    const bucket = map[key];
    if (bucket) {
      bucket.sort(
        (a, b) =>
          new Date(a.createdTime).getTime() - new Date(b.createdTime).getTime(),
      );
    }
  }
  // 组间按最新一条时间倒序（最新的组在前）
  return Object.entries(map)
    .map(([stateId, items]) => ({ stateId, items }))
    .sort((a, b) => {
      const lastA = new Date(a.items[a.items.length - 1]?.createdTime ?? 0).getTime();
      const lastB = new Date(b.items[b.items.length - 1]?.createdTime ?? 0).getTime();
      return lastB - lastA;
    });
}

/** 计算用时 */
function formatDuration(items: LogItem[]): string {
  if (items.length < 2) return '';
  const begin = new Date(items[0]?.createdTime ?? 0).getTime();
  const end = new Date(items[items.length - 1]?.createdTime ?? 0).getTime();
  const seconds = Math.round((end - begin) / 1000);
  if (seconds > 3600) {
    const h = Math.floor(seconds / 3600);
    const m = Math.floor((seconds % 3600) / 60);
    const s = seconds % 60;
    return `${String(h)}时${String(m)}分${String(s)}秒`;
  }
  if (seconds > 60) {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${String(m)}分${String(s)}秒`;
  }
  return `${String(seconds)}秒`;
}

/** 判断是否包含执行事件 */
function hasExecute(items: LogItem[]): boolean {
  return items.some((item) => item.event === 'execute' || item.event === 'change');
}

/** 格式化日志消息 — 匹配 iot-wfm formatMessage */
function formatMessage(item: LogItem): string {
  if (item.message) return item.message;
  switch (item.event) {
    case 'bootstrap':
      return `设备${item.cause ? `(原因:${item.cause})` : ''}开机`;
    case 'execute':
      return `执行流程${item.process?.name ? `: ${item.process.name}` : ''}`;
    case 'terminate':
      return '终止流程';
    case 'finish':
      return '完成流程';
    case 'offline':
      return '设备离线';
    default:
      return item.event;
  }
}

export function LogViewer({ logs }: { logs: LogItem[] }) {
  if (!logs || logs.length === 0) {
    return (
      <div style={{ color: '#999', textAlign: 'center', padding: 32 }}>
        暂无日志
      </div>
    );
  }

  const groups = groupByStateId(logs);

  return (
    <div>
      {groups.map((group, gi) => (
        <div key={group.stateId}>
          {gi > 0 && <Divider style={{ margin: '12px 0' }} />}
          <Timeline
            items={group.items.map((item, _idx) => ({
              color: eventColors[item.event] || 'gray',
              content: (
                <div style={{ fontSize: 14 }}>
                  <div
                    style={{
                      display: 'flex',
                      alignItems: 'center',
                      gap: 6,
                      marginBottom: 2,
                    }}
                  >
                    <Tag color={eventColors[item.event]}>
                      {eventLabels[item.event] || item.event}
                    </Tag>
                    <span style={{ color: '#999', fontSize: 12 }}>
                      {new Date(item.createdTime).toLocaleString('zh-CN', {
                        hour: '2-digit',
                        minute: '2-digit',
                        second: '2-digit',
                      })}
                    </span>
                  </div>
                  <div style={{ fontSize: 13, color: '#333' }}>
                    {formatMessage(item)}
                  </div>
                </div>
              ),
            }))}
          />
          {hasExecute(group.items) && (
            <div
              style={{
                color: '#999',
                fontSize: 12,
                marginTop: 4,
                marginLeft: 24,
              }}
            >
              用时 {formatDuration(group.items)}
            </div>
          )}
        </div>
      ))}
    </div>
  );
}

/**
 * 中断条件编辑器 — 编辑单个 Interrupt 的传感器、信号类型、阈值等参数
 *
 * 数字信号 vs 模拟信号：
 * - 数字信号（digital）：只有 0/1 两种状态，通过 Switch 开关配置触发状态
 * - 模拟信号（analog）：连续值，通过逻辑比较（>/<）和阈值判断是否触发
 *   两种类型共享同一 Interrupt 数据结构，通过 signalType 字段区分
 */

'use client';

import { Input, InputNumber, Switch, Select, Empty, Radio } from 'antd';

import type { GpioInfo } from '../hooks/use-device-config';
import type { Interrupt } from '../types';

export function ProcessInterruptEditor({
  interrupt,
  gpio,
  onChange,
  onRemove: _onRemove,
}: {
  interrupt: Interrupt;
  gpio: GpioInfo;
  onChange: (updated: Interrupt) => void;
  onRemove: () => void;
}) {
  const sensorOptions = (gpio.sensors ?? []).map((k) => ({
    value: k,
    label: k,
  }));

  const signalType = interrupt.signalType ?? 'digital';
  const logic = interrupt.logic ?? '>';
  const threshold = interrupt.threshold ?? 0;

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
      <div>
        <label style={{ fontSize: 13, color: '#666', marginBottom: 4, display: 'block' }}>
          中断名称
        </label>
        <Input
          value={interrupt.name}
          onChange={(e) => { onChange({ ...interrupt, name: e.target.value }); }}
          placeholder="输入中断名称"
        />
      </div>

      <div>
        <label style={{ fontSize: 13, color: '#666', marginBottom: 4, display: 'block' }}>
          传感器
        </label>
        {sensorOptions.length > 0 ? (
          <Select
            value={interrupt.component}
            onChange={(v) => { onChange({ ...interrupt, component: v }); }}
            options={sensorOptions}
            style={{ width: '100%' }}
          />
        ) : (
          <Empty
            image={Empty.PRESENTED_IMAGE_SIMPLE}
            description="设备无可用传感器（sensors），请等待设备上报 GPIO 状态"
            style={{ margin: '8px 0' }}
          />
        )}
      </div>

      <div>
        <label style={{ fontSize: 13, color: '#666', marginBottom: 4, display: 'block' }}>
          信号类型
        </label>
        <Radio.Group
          value={signalType}
          onChange={(e) =>
          { onChange({
            ...interrupt,
            signalType: e.target.value,
          }); }
          }
          optionType="button"
          buttonStyle="solid"
        >
          <Radio.Button value="digital">数字信号</Radio.Button>
          <Radio.Button value="analog">模拟信号</Radio.Button>
        </Radio.Group>
      </div>

      {/* 数字信号：显示触发状态开关 */}
      {signalType === 'digital' && (
        <div>
          <label style={{ fontSize: 13, color: '#666', marginBottom: 4, display: 'block' }}>
            触发状态
          </label>
          <Switch
            checked={interrupt.state === 1 || interrupt.state === true}
            onChange={(checked) =>
            { onChange({ ...interrupt, state: checked ? 1 : 0 }); }
            }
            checkedChildren="触发 (1)"
            unCheckedChildren="未触发 (0)"
          />
        </div>
      )}

      {/* 模拟信号：显示逻辑选择 + 触发阈值 */}
      {signalType === 'analog' && (
        <>
          <div>
            <label style={{ fontSize: 13, color: '#666', marginBottom: 4, display: 'block' }}>
              逻辑
            </label>
            <Radio.Group
              value={logic}
              onChange={(e) =>
              { onChange({
                ...interrupt,
                logic: e.target.value,
              }); }
              }
              optionType="button"
              buttonStyle="solid"
            >
              <Radio.Button value=">">大于</Radio.Button>
              <Radio.Button value="<">小于</Radio.Button>
            </Radio.Group>
          </div>

          <div>
            <label style={{ fontSize: 13, color: '#666', marginBottom: 4, display: 'block' }}>
              触发阈值
            </label>
            <InputNumber
              value={threshold}
              onChange={(v) =>
              { onChange({ ...interrupt, threshold: v ?? 0 }); }
              }
              min={0}
              step={1}
              style={{ width: '100%' }}
              placeholder="输入模拟信号触发阈值"
            />
            <div style={{ fontSize: 11, color: '#999', marginTop: 4 }}>
              当传感器值{logic === '>' ? '大于' : '小于'}阈值时触发中断
            </div>
          </div>
        </>
      )}

      <div>
        <label style={{ fontSize: 13, color: '#666', marginBottom: 4, display: 'block' }}>
          屏蔽抖动间隔（毫秒）
        </label>
        <InputNumber
          value={interrupt.intercept}
          onChange={(v) => { onChange({ ...interrupt, intercept: v ?? 0 }); }}
          step={100}
          min={0}
          style={{ width: '100%' }}
        />
        {/*
         * intercept 用于防抖：在首次触发中断后，该时间段内忽略同一传感器的重复触发。
         * 避免因信号抖动导致中断逻辑被多次执行。
         */}
      </div>

      <div>
        <label style={{ fontSize: 13, color: '#666', marginBottom: 4, display: 'block' }}>
          延迟检测（毫秒）
        </label>
        <InputNumber
          value={interrupt.delay}
          onChange={(v) => { onChange({ ...interrupt, delay: v ?? 0 }); }}
          step={1000}
          min={0}
          style={{ width: '100%' }}
        />
      </div>

      <div>
        <label style={{ fontSize: 13, color: '#666', marginBottom: 4, display: 'block' }}>
          持续时间（毫秒）
        </label>
        <InputNumber
          value={interrupt.duration}
          onChange={(v) => { onChange({ ...interrupt, duration: v ?? 0 }); }}
          step={1000}
          min={0}
          style={{ width: '100%' }}
        />
      </div>

      <div>
        <label style={{ fontSize: 13, color: '#666', marginBottom: 4, display: 'block' }}>
          禁用
        </label>
        <Switch
          checked={!interrupt.disabled}
          onChange={(checked) => { onChange({ ...interrupt, disabled: !checked }); }}
          checkedChildren="启用"
          unCheckedChildren="禁用"
        />
      </div>
    </div>
  );
}

/**
 * 电压检测配置抽屉 — 设置分压电阻 R1/R2 和传感器引脚
 */

'use client';

import { CloseOutlined } from '@ant-design/icons';
import { Drawer, Select, InputNumber, Button, Space } from 'antd';

import type { VoltageConfig } from '../types';

interface VoltageConfigDrawerProps {
  open: boolean;
  voltage: VoltageConfig | undefined;
  sensors: string[];
  onChange: (config: VoltageConfig | undefined) => void;
  onClose: () => void;
}

/**
 * 默认分压电阻值
 * R1=30kΩ 上拉至被测电压，R2=10kΩ 下拉至 GND
 * 分压比 = (R1+R2)/R2 = 4，适用于测量 0~13.2V 的电池电压（ESP32 ADC 最大 3.3V）
 */
const DEFAULT_R1 = 30000;
const DEFAULT_R2 = 10000;

export function VoltageConfigDrawer({
  open,
  voltage,
  sensors,
  onChange,
  onClose,
}: VoltageConfigDrawerProps) {
  const config = voltage || { sensor: sensors[0] || 'sensor_0', r1: DEFAULT_R1, r2: DEFAULT_R2 };

  function update(partial: Partial<VoltageConfig>) {
    onChange({ ...config, ...partial });
  }

  /**
   * 关闭抽屉
   *
   * 若原本无电压配置且设备无可用传感器，则放弃本次配置（设为 undefined），
   * 避免保存一个无意义的默认配置到设备。
   */
  function handleClose() {
    if (!voltage && !sensors.length) {
      onChange(undefined);
    }
    onClose();
  }

  return (
    <Drawer
      title="电压检测配置"
      placement="bottom"
      size="60%"
      open={open}
      onClose={handleClose}
      destroyOnClose
      extra={
        <Button
          icon={<CloseOutlined />}
          onClick={handleClose}
          size="small"
        >
          关闭
        </Button>
      }
    >
      <div style={{ display: 'flex', flexDirection: 'column', gap: 16 }}>
        {/* 传感器选择 */}
        <div>
          <label
            style={{
              fontSize: 13,
              color: '#666',
              marginBottom: 4,
              display: 'block',
            }}
          >
            电压检测传感器
          </label>
          <Select
            value={config.sensor}
            onChange={(v) => { update({ sensor: v }); }}
            options={sensors.map((s) => ({ value: s, label: s }))}
            placeholder="选择传感器引脚"
            style={{ width: '100%' }}
          />
          <div style={{ fontSize: 11, color: '#999', marginTop: 4 }}>
            选择用于电压检测的 ADC 传感器引脚
          </div>
        </div>

        {/* R1 电阻值 */}
        <div>
          <label
            style={{
              fontSize: 13,
              color: '#666',
              marginBottom: 4,
              display: 'block',
            }}
          >
            R1 电阻值（Ω）
          </label>
          <Space.Compact style={{ width: '100%' }}>
            <InputNumber
              value={config.r1}
              onChange={(v) => { update({ r1: v ?? DEFAULT_R1 }); }}
              min={0}
              step={1000}
              style={{ flex: 1 }}
              placeholder="默认 30000"
            />
            <Button disabled>Ω</Button>
          </Space.Compact>
          <div style={{ fontSize: 11, color: '#999', marginTop: 4 }}>
            分压电阻 R1，上拉至被测电压。默认 30kΩ
          </div>
        </div>

        {/* R2 电阻值 */}
        <div>
          <label
            style={{
              fontSize: 13,
              color: '#666',
              marginBottom: 4,
              display: 'block',
            }}
          >
            R2 电阻值（Ω）
          </label>
          <Space.Compact style={{ width: '100%' }}>
            <InputNumber
              value={config.r2}
              onChange={(v) => { update({ r2: v ?? DEFAULT_R2 }); }}
              min={0}
              step={1000}
              style={{ flex: 1 }}
              placeholder="默认 10000"
            />
            <Button disabled>Ω</Button>
          </Space.Compact>
          <div style={{ fontSize: 11, color: '#999', marginTop: 4 }}>
            分压电阻 R2，下拉至 GND。默认 10kΩ
          </div>
        </div>

        {/* 电压计算公式说明 */}
        <div
          style={{
            background: '#f6f8fa',
            border: '1px solid #e8e8e8',
            borderRadius: 6,
            padding: '12px 16px',
            fontSize: 12,
            color: '#666',
          }}
        >
          <div style={{ fontWeight: 600, marginBottom: 4 }}>计算公式</div>
          <div>
            V<sub>实际</sub> = V<sub>传感器</sub> × (R1 + R2) / R2
          </div>
          <div style={{ marginTop: 4 }}>
            当前分压比:{' '}
            {config.r1 > 0 && config.r2 > 0
              ? ((config.r1 + config.r2) / config.r2).toFixed(2)
              : '—'}
          </div>
        </div>
      </div>
    </Drawer>
  );
}

/**
 * 模拟器事件按钮 — 触发 getState / pushBootstrap / pushChange / pushFinish
 */

'use client';

import { PlayCircleOutlined, CloudUploadOutlined } from '@ant-design/icons';
import { Button, Space, Select, Input, Card } from 'antd';
import { useState } from 'react';

const CHANGE_TYPES = [
  { value: 'step_ready', label: 'step_ready (步骤就绪)' },
  { value: 'step_begin', label: 'step_begin (步骤开始)' },
  { value: 'step_end', label: 'step_end (步骤正常结束)' },
  { value: 'step_timeout', label: 'step_timeout (步骤超时)' },
  { value: 'step_interrupt', label: 'step_interrupt (步骤中断)' },
];

const CAUSE_OPTIONS = [
  { value: '0', label: '0 (正常上电)' },
  { value: '2', label: '2 (外部唤醒)' },
  { value: '4', label: '4 (定时器唤醒)' },
];

export function EventButtons({
  onGetState,
  onPushBootstrap,
  onPushChange,
  onPushFinish,
  loading,
}: {
  onGetState: () => Promise<void>;
  onPushBootstrap: (cause: string) => Promise<void>;
  onPushChange: (type: string, message: string) => Promise<void>;
  onPushFinish: () => Promise<void>;
  loading: boolean;
}) {
  const [changeType, setChangeType] = useState('step_begin');
  const [changeMessage, setChangeMessage] = useState('');
  const [bootstrapCause, setBootstrapCause] = useState('0');

  return (
    <Card title="模拟事件" size="small">
      <Space wrap orientation="vertical" style={{ width: '100%' }}>
        <Space wrap>
          <Button
            type="primary"
            icon={<CloudUploadOutlined />}
            onClick={() => onGetState()}
            loading={loading}
          >
            getState (轮询)
          </Button>
          <Button
            icon={<PlayCircleOutlined />}
            onClick={() => onPushBootstrap(bootstrapCause)}
            loading={loading}
          >
            bootstrap (开机)
          </Button>
          <Select
            value={bootstrapCause}
            onChange={setBootstrapCause}
            options={CAUSE_OPTIONS}
            style={{ width: 160 }}
          />
        </Space>

        <Space wrap>
          <Button
            icon={<PlayCircleOutlined />}
            onClick={() => onPushChange(changeType, changeMessage)}
            loading={loading}
          >
            change (步骤变更)
          </Button>
          <Select
            value={changeType}
            onChange={setChangeType}
            options={CHANGE_TYPES}
            style={{ width: 220 }}
          />
          <Input
            placeholder="message (可选)"
            value={changeMessage}
            onChange={(e) => { setChangeMessage(e.target.value); }}
            style={{ width: 200 }}
          />
        </Space>

        <Button
          icon={<PlayCircleOutlined />}
          onClick={() => onPushFinish()}
          loading={loading}
        >
          finish (流程完成)
        </Button>
      </Space>
    </Card>
  );
}

/**
 * IoT 模拟器 Hook — 模拟 ESP32 固件的 getState/pushState 请求周期
 */

'use client';

import { useState, useCallback, useRef } from 'react';

// ---- Types ----

export type GpioState = {
  buttons: Record<string, number>;
  sensors: Record<string, number>;
  loads: Record<string, number>;
};

export type DeviceIdentity = {
  chipId: string;
  macAddress: string;
  stateId: string;
};

export type LogEntry = {
  id: number;
  timestamp: string;
  direction: 'request' | 'response';
  url: string;
  method: string;
  body?: string;
  status?: number;
  error?: string;
};

// Default GPIO values matching the ESP32 firmware's 4-pump setup
const DEFAULT_GPIO: GpioState = {
  buttons: { button_0: 0, button_1: 0, button_2: 0, button_3: 0, button_4: 0 },
  sensors: { sensor_0: 1827, sensor_1: 0, sensor_2: 0, sensor_3: 0, sensor_4: 355 },
  loads: { load_0: 0, load_1: 0, load_2: 0, load_3: 0 },
};

// ---- Hook ----

export function useIotSimulator() {
  const [identity, setIdentity] = useState<DeviceIdentity>({
    chipId: '5872424',
    macAddress: '20:E7:C8:59:9B:28',
    stateId: '',
  });
  const [gpio, setGpio] = useState<GpioState>(DEFAULT_GPIO);
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [loading, setLoading] = useState(false);
  const nextId = useRef(0);

  const addLog = useCallback((entry: Omit<LogEntry, 'id' | 'timestamp'>) => {
    setLogs((prev) => [
      { ...entry, id: nextId.current++, timestamp: new Date().toLocaleTimeString('zh-CN', { hour12: false }) },
      ...prev,
    ]);
  }, []);

  /**
   * Build the query string matching the ESP32 firmware's NetworkExt.getStateQuery() order:
   * 1. Base fields: macAddress, chipId
   * 2. Custom params: event, stateId, cause, type, message, etc.
   * 3. Component states: buttons as sensor:button_x, sensors as sensor:sensor_x, loads as load:load_x
   */
  const buildQuery = useCallback(
    (extra: Record<string, string> = {}): string => {
      const params = new URLSearchParams();
      params.set('macAddress', identity.macAddress);
      params.set('chipId', identity.chipId);

      // Extra params (event, stateId, cause, type, message, etc.)
      for (const [k, v] of Object.entries(extra)) {
        if (v !== undefined && v !== '') {
          params.set(k, v);
        }
      }

      // Buttons: firmware sends them as sensor:button_x because
      // they are registered as TYPE_SENSOR in Process
      for (const [key, val] of Object.entries(gpio.buttons)) {
        params.set(`sensor:${key}`, String(val));
      }
      // Sensors: sensor:sensor_x
      for (const [key, val] of Object.entries(gpio.sensors)) {
        params.set(`sensor:${key}`, String(val));
      }
      // Loads: load:load_x
      for (const [key, val] of Object.entries(gpio.loads)) {
        params.set(`load:${key}`, String(val));
      }

      return params.toString();
    },
    [identity, gpio],
  );

  /** Fire a GET request to a local Next.js IoT API route */
  const sendRequest = useCallback(
    async (endpoint: string, extra: Record<string, string> = {}) => {
      const query = buildQuery(extra);
      const url = `/watering/api/${endpoint}?${query}`;

      addLog({ direction: 'request', url, method: 'GET' });
      setLoading(true);

      try {
        const res = await fetch(url);
        const text = await res.text();
        let body: string;
        try {
          body = JSON.stringify(JSON.parse(text), null, 2);
        } catch {
          body = text;
        }
        addLog({ direction: 'response', url, method: 'GET', status: res.status, body });

        // 自动更新 stateId — get-state 响应中 stateId 位于顶层，非 data 下
        if (endpoint === 'get-state') {
          try {
            const json = JSON.parse(text);
            if (json?.stateId) {
              setIdentity((prev) => ({ ...prev, stateId: json.stateId }));
            }
          } catch {
            // JSON 解析失败时忽略，stateId 保持旧值
          }
        }
      } catch (err: unknown) {
        console.error('[Watering Debug] fetch 请求失败:', {
          url,
          error: err instanceof Error ? err.message : String(err),
        });
        if (err instanceof Error && err.stack) console.error(err.stack);
        addLog({ direction: 'response', url, method: 'GET', error: err instanceof Error ? err.message : String(err) });
      } finally {
        setLoading(false);
      }
    },
    [buildQuery, addLog],
  );

  /**
   * 模拟 ESP32 固件的 getState 轮询请求
   *
   * 固件端定期调用此接口获取最新 switch 状态和 process 指令，
   * 传入本地 stateId 供服务端判断是否有变化。
   */
  const getState = useCallback(() => {
    return sendRequest('get-state', { stateId: identity.stateId });
  }, [sendRequest, identity.stateId]);

  /**
   * 模拟 ESP32 上电 bootstrap 事件 — 首次上线时上报 GPIO 状态并触发默认配置创建
   * @param cause 启动原因: "0"=正常上电，"2"=外部唤醒，"4"=定时器唤醒
   */
  const pushBootstrap = useCallback(
    (cause = '0') => {
      return sendRequest('push-state', { event: 'bootstrap', cause });
    },
    [sendRequest],
  );

  /**
   * 模拟 ESP32 步骤变更 change 事件 — 上报当前步骤的执行状态变化
   * @param type 变更类型: step_ready/step_begin/step_end/step_timeout/step_interrupt
   * @param message 可选的附加消息
   */
  const pushChange = useCallback(
    (type: string, message = '') => {
      const extra: Record<string, string> = {
        event: 'change',
        stateId: identity.stateId,
        type,
      };
      if (message) {
        extra.message = message;
      }
      return sendRequest('push-state', extra);
    },
    [sendRequest, identity.stateId],
  );

  /**
   * 模拟 ESP32 流程完成 finish 事件 — 通知服务端当前流程已执行完毕
   */
  const pushFinish = useCallback(() => {
    return sendRequest('push-state', { event: 'finish', stateId: identity.stateId });
  }, [sendRequest, identity.stateId]);

  const clearLogs = useCallback(() => { setLogs([]); }, []);

  return {
    identity,
    setIdentity,
    gpio,
    setGpio,
    logs,
    loading,
    // Actions
    getState,
    pushBootstrap,
    pushChange,
    pushFinish,
    clearLogs,
  };
}

/**
 * 设备详情/配置页
 *
 * 展示单个设备的完整配置编辑器，顶栏提供保存/删除/返回操作。
 * 通过 saveRef 模式将保存函数从 DeviceEditor 传递到 Header 按钮。
 */

'use client';

import { ArrowLeftOutlined, SaveOutlined, DeleteOutlined } from '@ant-design/icons';
import { Spin, Button, Popconfirm, message } from 'antd';
import { useRouter } from 'next/navigation';
import { use, useRef } from 'react';

import { DeviceEditor } from '../../components/device-editor';
import { useDeviceConfig } from '../../hooks/use-device-config';

/** 设备详情页 */
export default function DeviceDetailPage({
  params,
}: {
  /** Next.js 15 将动态路由参数以 Promise 形式传递，需 use() 解包 */
  params: Promise<{ chipId: string }>;
}) {
  const { chipId } = use(params);
  const router = useRouter();
  const { config, gpio, loading, save, remove } = useDeviceConfig(chipId);

  // DeviceEditor 将 handleSave 注册到此 ref，Header 保存按钮通过它触发保存
  const saveRef = useRef<() => Promise<void>>(async () => {});

  async function handleRemove() {
    try {
      await remove();
      message.success('设备已删除');
      router.push('/watering');
    } catch (err: unknown) {
      console.error('[Watering] 删除设备失败:', { chipId, message: err instanceof Error ? err.message : String(err), stack: err instanceof Error ? err.stack : undefined });
      message.error(err instanceof Error ? err.message : String(err) || '删除失败');
    }
  }

  if (loading || !config) {
    return (
      <div style={{ textAlign: 'center', padding: 48 }}>
        <Spin />
      </div>
    );
  }

  return (
    <div>
      {/* 页面内顶栏操作按钮 — 匹配 iot-wfm EditView header extra */}
      <div
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          padding: '12px 16px',
          background: '#fff',
          borderBottom: '1px solid #f0f0f0',
        }}
      >
        <h3 style={{ margin: 0, fontSize: 16 }}>{config.name || '设备配置'}</h3>
        <div style={{ display: 'flex', gap: 8 }}>
          <Button
            type="primary"
            icon={<SaveOutlined />}
            onClick={() => saveRef.current()}
          >
            保存
          </Button>
          <Popconfirm title="确认删除设备？不可恢复。" onConfirm={handleRemove}>
            <Button danger icon={<DeleteOutlined />}>
              删除
            </Button>
          </Popconfirm>
          <Button icon={<ArrowLeftOutlined />} onClick={() => { router.back(); }}>
            返回
          </Button>
        </div>
      </div>

      <DeviceEditor
        config={config}
        gpio={gpio}
        onSave={async (data) => {
          try {
            await save(data);
            message.success('配置已保存');
          } catch (err: unknown) {
            // 错误已在 useDeviceConfig 中记日志，此处仅提示用户
            message.error(err instanceof Error ? err.message : String(err) || '保存失败');
          }
        }}
        onRemove={handleRemove}
        saveRef={saveRef}
      />
    </div>
  );
}

