/**
 * 设备列表数据 Hook
 *
 * 首次加载后按 intervalMs（默认 15 秒）定时轮询刷新。
 * 组件卸载时自动清除定时器。
 */

'use client';

import { useState, useEffect, useCallback } from 'react';

import { getDevices } from '../actions';

import type { DeviceItem } from '../types';

/** 设备列表数据管理（自动轮询） */
export function useDevices(intervalMs = 15000) {
  const [devices, setDevices] = useState<DeviceItem[]>([]);
  const [loading, setLoading] = useState(false);

  const refresh = useCallback(async () => {
    setLoading(true);
    try {
      const data = await getDevices();
      setDevices(data);
    } catch (err) {
      // ERROR: 设备列表加载失败影响整个页面
      console.error('[Watering] 获取设备列表失败:', err);
      if (err instanceof Error && err.stack) console.error(err.stack);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    refresh();
    // 定时轮询：固件心跳 + 状态由服务端写入，前端定时拉取最新数据
    const timer = setInterval(refresh, intervalMs);
    return () => { clearInterval(timer); };
  }, [refresh, intervalMs]);

  return { devices, loading, refresh };
}

/**
 * 设备日志页
 *
 * 展示设备的 IoT 通信日志，支持刷新和清空。
 * 日志数据由 services/db.ts 存储，不自动轮询（需要手动加载）。
 */

'use client';

import { ArrowLeftOutlined, ReloadOutlined, DeleteOutlined } from '@ant-design/icons';
import { Button, Spin, Popconfirm, message } from 'antd';
import { useRouter } from 'next/navigation';
import { use, useEffect } from 'react';

import { LogViewer } from '../../components/log-viewer';
import { useDeviceLogs } from '../../hooks/use-device-logs';

/** 设备日志页 */
export default function DeviceLogsPage({
  params,
}: {
  /** Next.js 15 将动态路由参数以 Promise 形式传递，需 use() 解包 */
  params: Promise<{ chipId: string }>;
}) {
  const { chipId } = use(params);
  const router = useRouter();
  const { logs, loading, load, clear } = useDeviceLogs(chipId);

  // 组件挂载时加载日志（不自动轮询，日志数据量大）
  useEffect(() => {
    load();
  }, [load]);

  async function handleClear() {
    try {
      await clear();
      message.success('日志已清空');
      load();
    } catch (err: unknown) {
      console.error('[Watering] 清空日志失败:', { chipId, message: err instanceof Error ? err.message : String(err), stack: err instanceof Error ? err.stack : undefined });
      message.error(err instanceof Error ? err.message : String(err) || '清空日志失败');
    }
  }

  return (
    <div>
      {/* 页面内顶栏 — 匹配 iot-wfm LogsView header extra */}
      <div
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          padding: '12px 16px',
          background: '#fff',
          borderBottom: '1px solid #f0f0f0',
          marginBottom: 16,
        }}
      >
        <Button icon={<ArrowLeftOutlined />} onClick={() => { router.back(); }}>
          返回
        </Button>
        <div style={{ display: 'flex', gap: 8 }}>
          <Button icon={<ReloadOutlined />} onClick={load} loading={loading}>
            刷新
          </Button>
          <Popconfirm title="确认清空日志？" onConfirm={handleClear}>
            <Button icon={<DeleteOutlined />} danger>
              清空
            </Button>
          </Popconfirm>
        </div>
      </div>

      {/* 设备名 — 匹配 LogsView 的 device-name */}
      <div style={{ padding: '0 16px', marginBottom: 16 }}>
        <h3 style={{ margin: 0, fontSize: 16 }}>设备: {chipId}</h3>
      </div>

      {/* 日志内容 */}
      <div style={{ padding: '0 16px' }}>
        {loading && logs.length === 0 ? (
          <div style={{ textAlign: 'center', padding: 48 }}>
            <Spin />
          </div>
        ) : (
          <LogViewer logs={logs} />
        )}
      </div>
    </div>
  );
}

/**
 * 浇花帮手首页 — 设备列表
 *
 * 每 15 秒自动轮询设备状态，展示设备卡片列表。
 * 支持手动刷新，无设备时显示空状态提示。
 */

'use client';

import { ReloadOutlined } from '@ant-design/icons';
import { Button, Spin, Empty } from 'antd';

import { DeviceCard } from './components/device-card';
import { useDevices } from './hooks/use-devices';

export default function WateringPage() {
  const { devices, loading, refresh } = useDevices(15000);

  return (
    <div style={{ padding: '12px 16px' }}>
      {/* 操作栏 — 匹配 iot-wfm 的 #extra 插槽 */}
      <div
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          marginBottom: 12,
        }}
      >
        <h2 style={{ margin: 0, fontSize: 18, fontWeight: 600 }}>设备列表</h2>
        <Button
          icon={<ReloadOutlined />}
          onClick={refresh}
          loading={loading}
          size="small"
        >
          刷新
        </Button>
      </div>

      {/* 设备卡片列表 */}
      {loading && devices.length === 0 ? (
        <div style={{ textAlign: 'center', padding: 48 }}>
          <Spin />
        </div>
      ) : devices.length === 0 ? (
        <Empty description="暂无设备，等待 IoT 设备上线" />
      ) : (
        devices.map((device) => (
          <DeviceCard key={device.chipId} device={device} onRefresh={refresh} />
        ))
      )}
    </div>
  );
}

import { getDb } from '@/lib/db';
import { newId } from '@/lib/utils';

import type { DeviceConfig, DeviceState, DeviceItem } from '../types';

/**
 * SQLite WASM 将 JSON/TEXT 列作为字符串返回，需手动解析。
 * 此辅助函数安全地将 JSON 字符串解析为对象/数组，如果已经是对象则直接返回。
 */
function parseJSON<T>(value: unknown, fallback: T): T {
  if (value === null || value === undefined) return fallback;
  if (typeof value === 'object') return value as T;
  if (typeof value === 'string') {
    try {
      return JSON.parse(value) as T;
    } catch {
      return fallback;
    }
  }
  return fallback;
}

/**
 * 初始化浇花模块数据库表
 */
export async function initDb() {
  console.log('[INITDB] Starting initDb...');
  const db = getDb();
  console.log('[INITDB] getDb() returned, about to exec CREATE TABLE...');

  db.exec(`
    CREATE TABLE IF NOT EXISTS watering_devices (
      chip_id TEXT PRIMARY KEY,
      name TEXT NOT NULL,
      mac_address TEXT NOT NULL,
      processes JSON NOT NULL DEFAULT '[]',
      idle_sleep INTEGER NOT NULL DEFAULT 0,
      idle_timeout INTEGER NOT NULL DEFAULT 30000,
      boot_exec INTEGER NOT NULL DEFAULT -1,
      exec_delay INTEGER NOT NULL DEFAULT 0,
      schedules JSON NOT NULL DEFAULT '[]',
      voltage JSON,
      processes_version TEXT,
      created_time TEXT NOT NULL,
      last_write_time TEXT NOT NULL
    )
  `);

  // 为旧数据库添加 voltage 列（兼容无此列的旧表）
  try {
    db.exec('ALTER TABLE watering_devices ADD COLUMN voltage JSON');
  } catch {
    // 列已存在，忽略
  }

  // 为旧数据库添加 processes_version 列
  try {
    db.exec('ALTER TABLE watering_devices ADD COLUMN processes_version TEXT');
  } catch {
    // 列已存在，忽略
  }

  db.exec(`
    CREATE TABLE IF NOT EXISTS watering_device_state (
      chip_id TEXT PRIMARY KEY,
      state_id TEXT NOT NULL,
      switch TEXT NOT NULL DEFAULT 'off',
      buttons JSON,
      sensors JSON,
      loads JSON,
      current_index INTEGER,
      current_process JSON,
      message TEXT,
      last_tick_time INTEGER DEFAULT 0,
      last_write_time TEXT NOT NULL,
      FOREIGN KEY (chip_id) REFERENCES watering_devices(chip_id)
    )
  `);

  db.exec(`
    CREATE TABLE IF NOT EXISTS watering_logs (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      chip_id TEXT NOT NULL,
      event TEXT NOT NULL,
      state JSON,
      created_time TEXT NOT NULL
    )
  `);

  db.exec(`
    CREATE INDEX IF NOT EXISTS idx_watering_logs_chip_id
    ON watering_logs(chip_id, created_time DESC)
  `);
}

/**
 * 获取所有设备（含状态和在线信息）
 */
export async function getAllDevices(): Promise<DeviceItem[]> {
  const db = getDb();
  const rows = db.prepare(`
    SELECT d.chip_id, d.name, d.mac_address, d.processes, d.idle_sleep, d.idle_timeout,
           d.boot_exec, d.exec_delay, d.schedules, d.voltage, d.processes_version, d.created_time, d.last_write_time,
           s.state_id, s.switch, s.buttons, s.sensors, s.loads,
           s.current_index, s.current_process, s.message,
           s.last_tick_time as state_last_tick_time, s.last_write_time as state_last_write_time
    FROM watering_devices d
    LEFT JOIN watering_device_state s ON d.chip_id = s.chip_id
    ORDER BY d.name
  // SQLite WASM 驱动返回类型不完整，需用 any 中转以访问 snake_case 列名
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  `).all() as any[];

  const now = Date.now();
  return rows.map((row) => {
    const config: DeviceConfig = {
      chipId: row.chip_id,
      name: row.name,
      macAddress: row.mac_address,
      processes: parseJSON(row.processes, [] as DeviceConfig['processes']),
      idleSleep: !!row.idle_sleep,
      idleTimeout: row.idle_timeout,
      bootExec: row.boot_exec,
      execDelay: row.exec_delay,
      schedules: parseJSON(row.schedules, [] as DeviceConfig['schedules']),
      voltage: parseJSON(row.voltage, undefined as DeviceConfig['voltage']),
      processesVersion: row.processes_version ?? undefined,
      createdTime: row.created_time,
      lastWriteTime: row.last_write_time,
    };

    const item: DeviceItem = { ...config };

    if (row.state_id) {
      item.state = {
        chipId: row.chip_id,
        stateId: row.state_id,
        switch: row.switch,
        buttons: parseJSON(row.buttons, undefined as Record<string, number> | undefined),
        sensors: parseJSON(row.sensors, undefined as Record<string, number> | undefined),
        loads: parseJSON(row.loads, undefined as Record<string, number> | undefined),
        index: row.current_index ?? undefined,
        process: parseJSON(row.current_process, undefined as DeviceState['process']),
        message: row.message ?? undefined,
        lastWriteTime: row.state_last_write_time,
      };
      item.lastTickTime = row.state_last_tick_time;
      // 60 秒内心跳视为在线
      item.isOnline = row.state_last_tick_time && (now - row.state_last_tick_time) <= 60 * 1000;
    }

    return item;
  });
}

/**
 * 获取单个设备配置
 */
export async function getDeviceConfig(chipId: string): Promise<DeviceConfig | null> {
  const db = getDb();
  // SQLite WASM 驱动返回值类型不完整，无法精确标注
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const row = db.prepare('SELECT * FROM watering_devices WHERE chip_id = ?').get(chipId) as any;
  if (!row) return null;
  return {
    chipId: row.chip_id,
    name: row.name,
    macAddress: row.mac_address,
    processes: parseJSON(row.processes, [] as DeviceConfig['processes']),
    idleSleep: !!row.idle_sleep,
    idleTimeout: row.idle_timeout,
    bootExec: row.boot_exec,
    execDelay: row.exec_delay,
    schedules: parseJSON(row.schedules, [] as DeviceConfig['schedules']),
    voltage: parseJSON(row.voltage, undefined as DeviceConfig['voltage']),
    processesVersion: row.processes_version ?? undefined,
    createdTime: row.created_time,
    lastWriteTime: row.last_write_time,
  };
}

/**
 * 保存设备配置
 */
export async function saveDeviceConfig(config: DeviceConfig) {
  const db = getDb();

  // processesVersion 生成：对比旧值，变更时生成新版本
  const oldConfig = await getDeviceConfig(config.chipId);
  if (!config.processesVersion || !oldConfig) {
    config.processesVersion = newId();
  } else {
    const oldProcessesJson = JSON.stringify(oldConfig.processes);
    const newProcessesJson = JSON.stringify(config.processes);
    if (oldProcessesJson !== newProcessesJson) {
      config.processesVersion = newId();
    }
  }

  db.prepare(`
    INSERT INTO watering_devices (chip_id, name, mac_address, processes, idle_sleep, idle_timeout, boot_exec, exec_delay, schedules, voltage, processes_version, created_time, last_write_time)
    VALUES (@chip_id, @name, @mac_address, @processes, @idle_sleep, @idle_timeout, @boot_exec, @exec_delay, @schedules, @voltage, @processes_version, @created_time, @last_write_time)
    ON CONFLICT(chip_id) DO UPDATE SET
      name=@name, mac_address=@mac_address, processes=@processes, idle_sleep=@idle_sleep,
      idle_timeout=@idle_timeout, boot_exec=@boot_exec, exec_delay=@exec_delay,
      schedules=@schedules, voltage=@voltage, processes_version=@processes_version,
      last_write_time=@last_write_time
  `).run({
    '@chip_id': config.chipId,
    '@name': config.name,
    '@mac_address': config.macAddress,
    '@processes': JSON.stringify(config.processes),
    '@idle_sleep': config.idleSleep ? 1 : 0,
    '@idle_timeout': config.idleTimeout,
    '@boot_exec': config.bootExec,
    '@exec_delay': config.execDelay,
    '@schedules': JSON.stringify(config.schedules),
    '@voltage': config.voltage ? JSON.stringify(config.voltage) : null,
    '@processes_version': config.processesVersion ?? null,
    '@created_time': config.createdTime,
    '@last_write_time': config.lastWriteTime,
  });
}

/**
 * 删除设备
 */
export async function deleteDevice(chipId: string) {
  const db = getDb();
  db.prepare('DELETE FROM watering_device_state WHERE chip_id = ?').run(chipId);
  db.prepare('DELETE FROM watering_devices WHERE chip_id = ?').run(chipId);
}

/**
 * 获取设备状态
 */
export async function getDeviceState(chipId: string): Promise<DeviceState | null> {
  const db = getDb();
  // SQLite WASM 驱动返回值类型不完整
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const row = db.prepare('SELECT * FROM watering_device_state WHERE chip_id = ?').get(chipId) as any;
  if (!row) return null;
  return {
    chipId: row.chip_id,
    stateId: row.state_id,
    switch: row.switch,
    buttons: parseJSON(row.buttons, undefined as Record<string, number> | undefined),
    sensors: parseJSON(row.sensors, undefined as Record<string, number> | undefined),
    loads: parseJSON(row.loads, undefined as Record<string, number> | undefined),
    index: row.current_index ?? undefined,
    process: parseJSON(row.current_process, undefined as DeviceState['process']),
    message: row.message ?? undefined,
    lastWriteTime: row.last_write_time,
  };
}

/**
 * 保存设备状态（upsert）
 */
export async function saveDeviceState(state: DeviceState) {
  const db = getDb();
  db.prepare(`
    INSERT INTO watering_device_state (chip_id, state_id, switch, buttons, sensors, loads, current_index, current_process, message, last_tick_time, last_write_time)
    VALUES (@chip_id, @state_id, @switch, @buttons, @sensors, @loads, @current_index, @current_process, @message, @last_tick_time, @last_write_time)
    ON CONFLICT(chip_id) DO UPDATE SET
      state_id=@state_id, switch=@switch, buttons=@buttons, sensors=@sensors, loads=@loads,
      current_index=@current_index, current_process=@current_process, message=@message,
      last_tick_time=@last_tick_time, last_write_time=@last_write_time
  `).run({
    '@chip_id': state.chipId,
    '@state_id': state.stateId,
    '@switch': state.switch,
    '@buttons': state.buttons ? JSON.stringify(state.buttons) : null,
    '@sensors': state.sensors ? JSON.stringify(state.sensors) : null,
    '@loads': state.loads ? JSON.stringify(state.loads) : null,
    '@current_index': state.index ?? null,
    '@current_process': state.process ? JSON.stringify(state.process) : null,
    '@message': state.message ?? null,
    '@last_tick_time': Date.now(),
    '@last_write_time': state.lastWriteTime,
  });
}

/**
 * 更新心跳时间
 */
export async function updateTick(chipId: string) {
  const db = getDb();
  const now = Date.now();
  const existing = db.prepare('SELECT 1 FROM watering_device_state WHERE chip_id = ?').get(chipId);
  if (existing) {
    db.prepare('UPDATE watering_device_state SET last_tick_time = ? WHERE chip_id = ?').run([now, chipId]);
  }
}

/**
 * 获取设备日志
 */
export async function getDeviceLogs(chipId: string, limit = 100) {
  const db = getDb();
  const rows = db.prepare(
    'SELECT id, chip_id, event, state, created_time FROM watering_logs WHERE chip_id = ? ORDER BY created_time DESC LIMIT ?',
  // SQLite WASM 驱动返回值类型不完整
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  ).all([chipId, limit]) as any[];
  return rows.map((row) => ({
    id: row.id,
    chipId: row.chip_id,
    event: row.event,
    state: parseJSON(row.state, undefined as Record<string, unknown> | undefined),
    createdTime: row.created_time,
  }));
}

/**
 * 写入设备日志
 */
export async function writeDeviceLog(chipId: string, event: string, state?: Record<string, unknown>) {
  const db = getDb();
  db.prepare('INSERT INTO watering_logs (chip_id, event, state, created_time) VALUES (?, ?, ?, ?)').run([
    chipId,
    event,
    state ? JSON.stringify(state) : null,
    new Date().toISOString(),
  ]);
}

/**
 * 清空设备日志
 */
export async function clearDeviceLogs(chipId: string) {
  const db = getDb();
  db.prepare('DELETE FROM watering_logs WHERE chip_id = ?').run(chipId);
}

'use client';

import { unstableSetRender } from 'antd-mobile';
import { useEffect } from 'react';
import { createRoot } from 'react-dom/client';

/**
 * React 19 兼容层：antd-mobile v5 的命令式 API（Dialog.show/confirm 等）
 * 使用 react-dom 的 render/unmountComponentAtNode，这些在 React 19 中已移除。
 * 通过注入 unstableSetRender 使用 createRoot 替代。
 *
 * 注意：仅在客户端执行（"use client"），useEffect 确保在浏览器挂载后才注册。
 *
 * @see https://mobile.ant.design/guide/v5-for-19
 */

/**
 * 注册 createRoot 渲染器到 antd-mobile，使其命令式 API 在 React 19 中正常工作。
 * 将节点渲染到指定容器，返回卸载清理函数供 antd-mobile 内部调用。
 */
export function AntdMobileCompat() {
  useEffect(() => {
    unstableSetRender((node, container) => {
      // 用 React 18+ 的 createRoot API 替代已移除的 render()
      const root = createRoot(container);
      root.render(node);
      // 返回异步清理函数：antd-mobile 关闭弹窗时会调用此函数卸载组件
      return async () => { root.unmount(); };
    });
  }, []);

  return null;
}

/**
 * SQLite 数据库连接模块（WASM 实现）
 *
 * 基于 node-sqlite3-wasm，在 WASM 虚拟文件系统中运行。
 * 数据库文件路径由 DB_PATH 环境变量指定，默认 project_root/data/app.db。
 *
 * 注意事项：
 * - WAL 模式不受 WASM 虚拟文件系统支持，使用默认 DELETE 日志模式
 * - SCF 部署时 DB_PATH 应设为 /tmp/app.db（仅 /tmp 可写）
 * - 数据库实例为模块级单例，getDb() 负责懒初始化
 *
 * @see instrumentation.ts — 应用启动时预初始化数据库
 */

import { mkdirSync, existsSync } from 'fs';
import path from 'path';

import { Database } from 'node-sqlite3-wasm';

type SQLiteDB = Database;

/** 模块级数据库单例（懒初始化） */
let db: SQLiteDB | null = null;

/** 数据库文件路径（支持环境变量覆盖，SCF 下需设为 /tmp/） */
const DB_PATH = process.env.DB_PATH || path.join(process.cwd(), 'data', 'app.db');

// DEBUG: 模块加载时打印运行时上下文，方便排查 SCF 与本地路径差异
if (process.env.NODE_ENV !== 'production') {
  console.log('[DB] process.cwd():', process.cwd());
  console.log('[DB] DB_PATH:', DB_PATH);
  console.log('[DB] process.env.NEXT_RUNTIME:', process.env.NEXT_RUNTIME);
}

/**
 * 获取数据库实例（懒初始化）
 *
 * 首次调用时创建数据库文件所在目录、初始化连接。
 * 后续调用直接返回缓存的单例。
 */
export function getDb(): SQLiteDB {
  if (db) {
    // DEBUG: 返回缓存实例（非生产打印指针地址辅助排查内存问题）
    if (process.env.NODE_ENV !== 'production') {
      // _ptr 是 node-sqlite3-wasm 内部属性，仅用于调试
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      console.log('[DB] Returning cached db instance, ptr:', (db as any)._ptr);
    }
    return db;
  }

  // INFO: 首次初始化，打印关键状态
  console.log('[DB] Initializing database...');
  const initStart = Date.now();

  const dir = path.dirname(DB_PATH);
  if (!existsSync(dir)) {
    // INFO: 目录不存在则创建（SCF /tmp 冷启动场景）
    console.log('[DB] Creating data directory:', dir);
    mkdirSync(dir, { recursive: true });
  }

  try {
    db = new Database(DB_PATH);
    const elapsed = Date.now() - initStart;
    console.log(`[DB] Database initialized at ${DB_PATH} (${String(elapsed)}ms)`);

    // WAL 模式在 WASM (Emscripten VFS) 和只读文件系统中不受支持，
    // 使用默认的 DELETE 日志模式，兼容性最好
  } catch (e) {
    // ERROR: 数据库创建失败，打印上下文和堆栈
    console.error(`[DB] Failed to create database at ${DB_PATH}:`, e);
    if (e instanceof Error && e.stack) console.error(e.stack);
    throw e;
  }
  return db;
}

/**
 * 同步获取已初始化的数据库实例
 *
 * 仅应在确认 getDb() 已调用后使用（如 instrumentation.ts 预初始化之后）。
 * 若未初始化则抛出异常，避免隐式初始化导致的时序问题。
 */
export function getDbSync(): SQLiteDB {
  if (!db) {
    throw new Error('[DB] Database not initialized. Call getDb() first.');
  }
  return db;
}

/**
 * OSS 对象存储适配器层
 *
 * 设计模式：策略 + 工厂，参考旧项目 XpnOssAdapter 接口 + TencentOss 实现。
 *
 * 接口层（OssAdapter）屏蔽底层 SDK 差异：
 * - TencentCosAdapter 基于 cos-nodejs-sdk-v5 实现（当前唯一实现）
 * - 后续如需支持阿里云 OSS，只需新增 AliOssAdapter 实现同一接口
 *
 * 工厂方法 getOssAdapter() 根据环境变量自动选择适配器并初始化。
 *
 * 环境变量：
 * - OSS_ENDPOINT: 存储区域，如 ap-beijing
 * - OSS_SECRET_ID: 密钥标识 (对应旧项目 key)
 * - OSS_SECRET_KEY: 通讯密钥 (对应旧项目 secret)
 * - OSS_BUCKET: 存储空间名称
 */

import COS from 'cos-nodejs-sdk-v5';

/** COS SDK 回调错误 — CosSdkError 运行时是 Error 实例，包含 stack */
type OssErr = { statusCode?: number; message?: string; stack?: string };

/** headObject 回调 data（仅判真值） */
// eslint-disable-next-line @typescript-eslint/no-empty-object-type
type HeadObjData = {};

/** getObject 回调 data（取 Body） */
type GetObjData = { Body: Buffer };

/** getObjectUrl 回调 data（取 Url） */
type GetObjUrlData = { Url: string };

// ─── 适配器接口（参考 XpnOssAdapter） ────────────────────────────────────

/**
 * OSS 适配器接口
 *
 * 对应旧项目 XpnOssAdapter，方法签名保持一致。
 * 各方法语义参考 TencentOss 实现。
 */
export interface OssAdapter {
  /** 获得目标存储主机 */
  getEndpoint(): string;
  /** 设置目标存储主机 */
  setEndpoint(value: string): void;
  /** 设置身份标识 */
  setKey(value: string): void;
  /** 设置通讯密钥 */
  setSecret(value: string): void;
  /** 获得空间名称 */
  getBucket(): string;
  /** 设置空间名称 */
  setBucket(value: string): void;
  /** 判断文件是否存在 */
  exists(path: string): Promise<boolean>;
  /** 获得文件内容（字符串） */
  getString(path: string): Promise<string>;
  /** 获得上传签名 URL */
  getSignedPutUrl(path: string, options?: OssPutOptions): Promise<string>;
  /** 获得下载签名 URL */
  getSignedUrl(path: string, options?: OssPutOptions): Promise<string>;
  /** 上传字符串 */
  putString(path: string, content: string, options?: OssPutOptions): Promise<void>;
  /** 追加字符串（读-改-写，非原子操作） */
  appendString(path: string, content: string, options?: OssPutOptions): Promise<void>;
  /** 删除内容 */
  delete(path: string): Promise<void>;
}

/**
 * 上传数据选项（参考 XpnOssPutOptions）
 */
export type OssPutOptions = {
  headers?: OssPutHeaders;
};

/**
 * 上传数据头部描述（参考 XpnOssPutHeaders）
 */
export type OssPutHeaders = Record<string, string> & {
  'Cache-Control'?: string;
  'Content-Disposition'?: string;
  'Content-Encoding'?: string;
  'Content-Type'?: string;
  Expires?: string;
};

// ─── 腾讯云 COS 适配器（参考 TencentOss） ────────────────────────────────

/**
 * 腾讯云 COS 适配器
 *
 * 参考 TencentOss 实现，使用 cos-nodejs-sdk-v5。
 * https://cloud.tencent.com/document/product/436/8629
 */
export class TencentCosAdapter implements OssAdapter {
  /**
   * 目标存储主机（Region）
   */
  protected _endpoint: string = 'ap-beijing';

  /**
   * 身份标识（SecretId）
   */
  protected _key: string = '';

  /**
   * 通讯密钥（SecretKey）
   */
  protected _secret: string = '';

  /**
   * 空间名称（Bucket）
   */
  protected _bucket: string = '';

  /**
   * SDK 指针（懒初始化，参考 TencentOss._sdk）
   */
  protected _sdk?: COS;

  public getEndpoint(): string {
    return this._endpoint;
  }

  public setEndpoint(value: string): void {
    this._endpoint = value;
  }

  public setKey(value: string): void {
    this._key = value;
  }

  public setSecret(value: string): void {
    this._secret = value;
  }

  public getBucket(): string {
    return this._bucket;
  }

  public setBucket(value: string): void {
    this._bucket = value;
  }

  /**
   * 获得 SDK 指针
   *
   * 参考 TencentOss.getSdk()，懒初始化 COS 客户端。
   */
  public getSdk(): COS {
    if (!this._sdk) {
      // INFO: 关键状态变更 — 首次创建 COS 客户端实例
      console.log(`[OSS] Creating COS client (Bucket=${this._bucket}, Region=${this._endpoint})`);
      this._sdk = new COS({
        SecretId: this._key,
        SecretKey: this._secret,
        Protocol: 'https:',
      });
    }
    return this._sdk;
  }

  /**
   * 判断文件是否存在
   *
   * 参考 TencentOss.exists()，使用 headObject 探测。
   * 404 视为文件不存在（正常情况），403 及其他错误视为异常。
   */
  public exists(path: string): Promise<boolean> {
    const start = Date.now();
    return new Promise((resolve, reject) => {
      this.getSdk().headObject(
        {
          Bucket: this.getBucket(),
          Region: this.getEndpoint(),
          Key: path,
        },
        (err: OssErr | null, _data: HeadObjData) => {
          const elapsed = Date.now() - start;
          if (!_data && err) {
            if (err.statusCode === 404) {
              // DEBUG: 文件不存在是正常查询结果，非错误
              if (elapsed > 500) console.log(`[OSS] headObject 404 (${String(elapsed)}ms) path=${path}`);
              resolve(false);
            } else if (err.statusCode === 403) {
              // ERROR: 权限不足，打印堆栈和上下文方便排查
              console.error(`[OSS] headObject 403 (${String(elapsed)}ms) path=${path}:`, err.message || err);
              if (err?.stack) console.error(err.stack);
              reject(err);
            } else {
              // ERROR: 其他网络或服务端错误
              console.error(`[OSS] headObject error (${String(elapsed)}ms) path=${path} statusCode=${String(err.statusCode)}:`, err.message || err);
              if (err?.stack) console.error(err.stack);
              reject(err);
            }
          } else {
            if (elapsed > 500) console.log(`[OSS] headObject OK (${String(elapsed)}ms) path=${path}`);
            resolve(true);
          }
        },
      );
    });
  }

  /**
   * 获得文件内容（UTF-8 字符串）
   *
   * 参考 TencentOss.getString()。
   */
  public getString(path: string): Promise<string> {
    const start = Date.now();
    return new Promise((resolve, reject) => {
      this.getSdk().getObject(
        {
          Bucket: this.getBucket(),
          Region: this.getEndpoint(),
          Key: path,
        },
        (err: OssErr | null, data: GetObjData) => {
          const elapsed = Date.now() - start;
          if (data) {
            const str = data.Body.toString('utf-8');
            if (elapsed > 500) console.log(`[OSS] getObject OK (${String(elapsed)}ms) path=${path}`);
            resolve(str); return;
          }
          // ERROR: 下载失败，打印堆栈和上下文
          console.error(`[OSS] getObject failed (${String(elapsed)}ms) path=${path}:`, err?.message || err);
          if (err?.stack) console.error(err.stack);
          reject(err);
        },
      );
    });
  }

  /**
   * 获得上传签名 URL
   *
   * 参考 TencentOss.getSignedPutUrl()。
   * 签名 URL 包含临时鉴权参数，客户端可直接用于 PUT 上传。
   */
  public getSignedPutUrl(
    path: string,
    options?: OssPutOptions,
  ): Promise<string> {
    const start = Date.now();
    return new Promise((resolve, reject) => {
      this.getSdk().getObjectUrl(
        {
          Bucket: this.getBucket(),
          Region: this.getEndpoint(),
          Key: path,
          Method: 'PUT',
          Sign: true,
          Headers: options?.headers,
        },
        (err: OssErr | null, data: GetObjUrlData) => {
          const elapsed = Date.now() - start;
          if (err) {
            // ERROR: 签名 URL 生成失败，打印堆栈和上下文
            console.error(`[OSS] getSignedPutUrl failed (${String(elapsed)}ms) path=${path}:`, err?.message || err);
            if (err?.stack) console.error(err.stack);
            reject(err); return;
          }
          if (elapsed > 500) console.log(`[OSS] getSignedPutUrl OK (${String(elapsed)}ms) path=${path}`);
          resolve(data.Url);
        },
      );
    });
  }

  /**
   * 获得下载签名 URL
   *
   * 参考 TencentOss.getSignedUrl()。
   * 签名 URL 包含临时鉴权参数，客户端可直接用于 GET 下载。
   */
  public getSignedUrl(
    path: string,
    options?: OssPutOptions,
  ): Promise<string> {
    const start = Date.now();
    return new Promise((resolve, reject) => {
      this.getSdk().getObjectUrl(
        {
          Bucket: this.getBucket(),
          Region: this.getEndpoint(),
          Key: path,
          Method: 'GET',
          Sign: true,
          Headers: options?.headers,
        },
        (err: OssErr | null, data: GetObjUrlData) => {
          const elapsed = Date.now() - start;
          if (err) {
            // ERROR: 签名 URL 生成失败，打印堆栈和上下文
            console.error(`[OSS] getSignedUrl failed (${String(elapsed)}ms) path=${path}:`, err?.message || err);
            if (err?.stack) console.error(err.stack);
            reject(err); return;
          }
          if (elapsed > 500) console.log(`[OSS] getSignedUrl OK (${String(elapsed)}ms) path=${path}`);
          resolve(data.Url);
        },
      );
    });
  }

  /**
   * 上传字符串
   *
   * 参考 TencentOss.putString()，自动设置 Content-Type 为 text/plain;charset=UTF-8。
   * 若 options.headers 中已指定 Content-Type，则使用指定值。
   */
  public putString(
    path: string,
    content: string,
    options?: OssPutOptions,
  ): Promise<void> {
    const start = Date.now();
    return new Promise((resolve, reject) => {
      if (!options) {
        options = {};
      }
      if (!options.headers) {
        options.headers = {};
      }
      if (!('Content-Type' in options.headers)) {
        options.headers['Content-Type'] = 'text/plain;charset=UTF-8';
      }

      this.getSdk().putObject(
        {
          Bucket: this.getBucket(),
          Region: this.getEndpoint(),
          Key: path,
          ContentType: options.headers['Content-Type'],
          ContentEncoding: options.headers['Content-Encoding'],
          Body: content,
        },
        (err: OssErr | null, _data: unknown) => {
          const elapsed = Date.now() - start;
          if (err) {
            // ERROR: 上传失败，打印堆栈和上下文
            console.error(`[OSS] putObject failed (${String(elapsed)}ms) path=${path}:`, err?.message || err);
            if (err?.stack) console.error(err.stack);
            reject(err); return;
          }
          if (elapsed > 500) console.log(`[OSS] putObject OK (${String(elapsed)}ms) path=${path}`);
          resolve();
        },
      );
    });
  }

  /**
   * 追加字符串
   *
   * 参考 TencentOss.appendString()，非原子操作（读取旧内容 → 拼接 → 写回）。
   */
  public async appendString(
    path: string,
    content: string,
    options?: OssPutOptions,
  ): Promise<void> {
    let newContent: string;
    if (await this.exists(path)) {
      const oldContent = await this.getString(path);
      newContent = oldContent + content;
    } else {
      newContent = content;
    }
    await this.putString(path, newContent, options);
  }

  /**
   * 删除对象
   *
   * 参考 TencentOss.delete()。
   */
  public delete(path: string): Promise<void> {
    const start = Date.now();
    return new Promise((resolve, reject) => {
      this.getSdk().deleteObject(
        {
          Bucket: this.getBucket(),
          Region: this.getEndpoint(),
          Key: path,
        },
        (err: OssErr | null, _data: unknown) => {
          const elapsed = Date.now() - start;
          if (err) {
            // ERROR: 删除失败，打印堆栈和上下文
            console.error(`[OSS] deleteObject failed (${String(elapsed)}ms) path=${path}:`, err?.message || err);
            if (err?.stack) console.error(err.stack);
            reject(err); return;
          }
          if (elapsed > 500) console.log(`[OSS] deleteObject OK (${String(elapsed)}ms) path=${path}`);
          resolve();
        },
      );
    });
  }
}

// ─── 全局单例 ──────────────────────────────────────────────────────────

let adapterInstance: OssAdapter | null = null;

/**
 * 检查 OSS 是否已配置
 *
 * 四个环境变量全部非空时视为已配置。
 */
export function isOssConfigured(): boolean {
  return (
    !!process.env.OSS_ENDPOINT &&
    !!process.env.OSS_SECRET_ID &&
    !!process.env.OSS_SECRET_KEY &&
    !!process.env.OSS_BUCKET
  );
}

/**
 * 获取 OSS 适配器单例
 *
 * 参考 XpnOss.factory() 工厂模式，根据环境变量创建适配器。
 * 当前仅支持腾讯云 COS，后续可扩展。
 */
export function getOssAdapter(): OssAdapter {
  if (adapterInstance) {
    return adapterInstance;
  }

  if (!isOssConfigured()) {
    throw new Error(
      'OSS 未配置。请设置 OSS_ENDPOINT, OSS_SECRET_ID, OSS_SECRET_KEY, OSS_BUCKET 环境变量。',
    );
  }

  // 工厂模式：参考 XpnOss.factory()，根据配置创建对应适配器
  // INFO: 关键状态变更 — 首次创建 OSS 适配器单例
  console.log(`[OSS] Creating TencentCosAdapter (Bucket=${String(process.env.OSS_BUCKET)}, Region=${String(process.env.OSS_ENDPOINT)})`);
  const adapter = new TencentCosAdapter();
  // eslint-disable-next-line @typescript-eslint/no-non-null-assertion -- isOssConfigured() 已确保四个环境变量均非空
  adapter.setEndpoint(process.env.OSS_ENDPOINT!);
  // eslint-disable-next-line @typescript-eslint/no-non-null-assertion -- isOssConfigured() 已确保四个环境变量均非空
  adapter.setKey(process.env.OSS_SECRET_ID!);
  // eslint-disable-next-line @typescript-eslint/no-non-null-assertion -- isOssConfigured() 已确保四个环境变量均非空
  adapter.setSecret(process.env.OSS_SECRET_KEY!);
  // eslint-disable-next-line @typescript-eslint/no-non-null-assertion -- isOssConfigured() 已确保四个环境变量均非空
  adapter.setBucket(process.env.OSS_BUCKET!);

  adapterInstance = adapter;
  return adapterInstance;
}

/**
 * 重置 OSS 适配器（主要用于测试）
 */
export function resetOssAdapter(): void {
  adapterInstance = null;
}
